quests[29596] = { id = 29596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Exarchen", description = "Exarch Maladaar übt sein unheiliges Werk im tiefsten Teil der Krypta aus. Er stellt eine Bedrohung für unser beider Welten dar und muss aufgehalten werden.\n\nTötet ihn zum Wohle aller, dem der Toten und dem der Lebenden.", sourceObjective = "Tötet Exarch Maladaar und kehrt zu dem Draeneigeist in der Auchenaikrypta zurück.", completion = "Ihr habt unserem Reich einen großen Dienst erwiesen. Wir werden Euch nicht vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29598] = { id = 29598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarethas Ablenkungsmanöver", description = "Taretha war es, die ursprünglich für das Ablenkungsmanöver in Durnholde sorgte und Thrall die Flucht ermöglichte.\n\nNun haben die Ewigen Taretha gefangen genommen. Wenn wir nicht eingreifen, wird es kein Ablenkungsmanöver geben. Nehmt die Brandsätze, die ich Euch gegeben habe, und brennt die Internierungsbaracken nieder.", sourceObjective = "Reist nach Burg Durnholde und platziert mithilfe des Bündels mit Brandbomben, das Ihr von Erozion erhalten habt, 5 Brandsätze auf den Fässern in jeder Internierungsbaracke.\n\nSprecht mit Thrall im Kellergefängnis von Burg Durnholde, wenn Ihr die Internierungsbaracken angezündet habt.", progress = "Wer seid Ihr?", completion = "Ihr seid mit Taretha befreundet? Das ist also ihr neuer Plan. Nun gut…", sourceObjectiveStatus = "unverified-source-field" }
quests[29599] = { id = 29599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus Durnholde", description = "Ich habe große Pläne für mein Volk, <Fremder/Fremde>.\n\nEines Tages wird es seine Unterdrücker stürzen und sich erheben. Es wird die Ketten sprengen, die es halten und dies wird die Geburtsstunde der orcischen Horde sein.\n\nWir fliehen, wenn Ihr bereit seid.", sourceObjective = "Gebt Thrall Bescheid, wenn Ihr bereit seid. Folgt Thrall aus der Burg Durnholde und helft ihm, Taretha zu befreien und sein Schicksal zu erfüllen.\n\nSprecht mit Erozion im Alten Hügelland, wenn Ihr diese Aufgabe erfüllt habt.", completion = "Ihr habt eine großartige Aufgabe vollbracht, {name}. Nun müssen die Erinnerungen des jungen Kriegshäuptlings an diese Ereignisse wieder so verändert werden, wie sie einst waren...", sourceObjectiveStatus = "unverified-source-field" }
quests[29600] = { id = 29600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnelles Urteil", description = "Diese Teiche sind etwas ganz Besonderes: In Pandaria gibt es sonst keinen Ort, der Leben so viel Nahrung bietet.\n\nLeider hat das auch die Aufmerksamkeit der einheimischen Fauna auf sich gezogen. Vor kurzem haben Drachenschildkröten herausgefunden, dass es auf der Ebene direkt über uns viele Teiche voller Krötenlaich gibt. Jetzt haben sie sich dort oben breitgemacht, trampeln die Lotusblüten nieder und greifen meine Arbeiter an.\n\nEinzeltiere sind nicht sonderlich gefährlich, aber in Gruppen können sie ganz schön gemein sein. Bitte, wenn Ihr ein wenig Kraft erübrigen könnt, helft uns, sie loszuwerden.", sourceObjective = "Tötet 16 Klingenrückenschnapper bei den Teichen der Reinheit.", completion = "Ich bin Euch dankbar, {name}.\n\nBitte nehmt dies als Zeichen meiner Wertschätzung.", sourceObjectiveStatus = "unverified-source-field" }
quests[29605] = { id = 29605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruder gegen Bruder", description = "Die Sethekk verließen Skettis, als Auchindoun explodierte.\n\nMein Bruder Syth gehörte zu ihren Anführern. Auf seinen Befehl suchten wir die Ruinen auf und stellten uns unserem Gott.\n\nNach kurzer Zeit warf mich Syth jedoch aus den Hallen, weil mir Zweifel an ihren Fähigkeiten kamen. Er erlaubte mir nicht, meine Schwester Lakka mitzunehmen. Werdet Ihr mir helfen, sie zu retten?", sourceObjective = "Befreit Lakka aus ihrer Gefangenschaft. Kehrt zu Isfar in den Sethekkhallen zurück, wenn Ihr die Rettung abgeschlossen habt.", completion = "Zu wissen, dass Lakka frei ist, bedeutet, dass ich endlich all meine Bande zu den Sethekk abwerfen kann.\n\nEin Teil von mir wird mir Syths Tod niemals verzeihen, aber es musste getan werden. Ich werde die Todesriten für ihn vollziehen, wenn ich in Skettis ankomme.", sourceObjectiveStatus = "unverified-source-field" }
quests[29606] = { id = 29606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokks Erbe", description = "Terokk, der Held von Arakkoa, verschwand eines Tages plötzlich und ließ nur seine Maske und seinen Speer zurück.\n\nDunkelwirker Syth hat sie immer noch in seinem Besitz und Klauenkönig Ikiss wacht über seinen Speer.\n\nEs würde meinem Volk viel bedeuten, wenn wir die Gegenstände zurückbekommen würden.", sourceObjective = "Bringt Terokks Maske und Terokks Federkiel zu Isfar in den Sethekkhallen.", progress = "Die Relikte von Terokk sind schon viel zu lange aus Skettis fort. Konntet Ihr sie von den Sethekk zurückholen?", completion = "Vielleicht wird mir meine Rolle bei den Verbrechen der Sethekk niemals vergeben werden, aber ich möchte versuchen, meine Sünden zu büßen, indem ich die Relikte von Terokk meinem Volk zurückgebe", sourceObjectiveStatus = "unverified-source-field" }
quests[29607] = { id = 29607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen der Begierde", description = "Ich habe einen Kunden, der sich für die Augen der kobaltblauen Schlangen interessiert, die sich hier angesiedelt haben.\n\nWenn Ihr mir einige dieser seltenen Edelsteine besorgen könntet, würde ich den Profit mit Euch teilen.\n\nEinverstanden?", sourceObjective = "Händler Vijaad in den Sethekkhallen möchte, dass Ihr ihm 3 Kobaltaugen bringt.", progress = "Habt Ihr die Augen bekommen?", completion = "Wunderbare Stücke, gut gemacht!\n\nHier ist Euer Anteil, wie versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29608] = { id = 29608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündete in Dalaran", description = "Willkommen in Nordend, {name}. Man hat mich gebeten, die Reise nach Dalaran für Euch zu arrangieren, damit Ihr dort unsere Verbündeten treffen könnt.\n\nReitet auf einem Greifen nach Dalaran und sucht nach der Landung unser Gasthaus Zum Gefeierten Helden auf. Sprecht dort mit Isirami Sanftwind.\n\nSie wird Euch dabei helfen, Euren Ruhestein an die Stadt zu binden. Mit dem Portal in der Silbernen Enklave könnt Ihr dann rasch nach Sturmwind zurückreisen.", sourceObjective = "Macht einen Greifenritt nach Dalaran und sprecht mit Isirami Sanftwind im Gasthaus Zum Gefeierten Helden.", completion = "Willkommen in Dalaran! Dieses Gasthaus gehört zur Silbernen Enklave, dem offiziellen Hauptquartier der Allianz in dieser Stadt.\n\nVergesst nicht, Euren Ruhestein hier zu binden, damit Ihr rasch in die Stadt reisen und nebenan das Portal nach Sturmwind nutzen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29609] = { id = 29609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freunde in Dalaran", description = "Willkommen in Nordend. Man hat mich gebeten, Eure Reise nach Dalaran zu arrangieren, damit Ihr unsere Freunde in der Stadt kennenlernen könnt.\n\nSprecht mit mir und nehmt einen Flug nach Dalaran an. Begebt Euch nach der Landung zum Gasthaus \"Das Rattenloch\".\n\nRedet dort mit Uda dem Biest.\n\nSie wird Euch dabei helfen, Euren Ruhestein an die Stadt zu binden. Dann könnt Ihr durch das Portal in Sonnenhäschers Zuflucht rasch nach Orgrimmar reisen.", sourceObjective = "Lasst Euch vom Flugmeister einen Flug nach Dalaran geben und sprecht mit Uda dem Biest im Rattenloch.", completion = "Ich habe Euch erwartet. Dieses Gasthaus gehört zu Sonnenhäschers Zuflucht, der Hordenenklave von Dalaran.\n\nDenkt daran, Euren Ruhestein hier zu binden, damit Ihr rasch zur Stadt kommen und das Portal nach Orgrimmar, draußen neben dem Brunnen, benutzen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29611] = { id = 29611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst des Krieges", description = "Lok'tar ogar, {race}. Ich bin Nazgrim.\n\nHiermit befehle ich Euch, Euch unverzüglich bei Garrosh Höllschrei in der Feste Grommash zu melden.\n\nAuf seinen Erlass hin haben alle im Dienst der Horde ihrem neuen Kriegshäuptling die Treue zu schwören.\n\nLasst ihn lieber nicht warten, {race}.", sourceObjective = "Sprecht mit General Nazgrim in der Feste Grommash.", completion = "Ah, gut. Ihr seid da. Und keinen Augenblick zu früh...", sourceObjectiveStatus = "unverified-source-field" }
quests[29612] = { id = 29612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst des Krieges", description = "Lok'tar ogar, alter Freund. Es ist schon zu lange her, seit wir miteinander gesprochen haben.\n\nEs freut mich zu sehen, dass Ihr heil aus den Tiefen von Vashj'ir hervorgekommen seid.\n\nKriegshäuptling Höllschrei hat mich hier in der Feste Grommash stationiert.\n\nAuf seinen Erlass hin haben alle im Dienst der Horde ihrem neuen Kriegshäuptling die Treue zu schwören.\n\nLasst ihn lieber nicht warten, {name}.", sourceObjective = "Sprecht mit General Nazgrim in der Feste Grommash in Orgrimmar.", completion = "Ah, gut. Ihr seid da. Und keinen Augenblick zu früh...", sourceObjectiveStatus = "unverified-source-field" }
quests[29613] = { id = 29613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gerechtes Schicksal", description = "Kriegsherr Kalithresh leitet Operation Dampfkammer.\n\nEr muss sterben, {name}. Die Naga lassen uns keine andere Wahl als Gewalt.\n\nZeigt ihm keine Gnade.", sourceObjective = "Tötet Kriegsherr Kalithresh und kehrt zu Behüterin Jhang in der Dampfkammer zurück.", completion = "Ich wünschte, das wäre nicht nötig gewesen, aber die Naga haben alle Verhandlungsangebote abgelehnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29614] = { id = 29614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindämmung ist der Schlüssel", description = "Die Naga haben sich mit den Lepragnomen verbündet, um eine schreckliche Krankheit in den Zangarmarschen zu verbreiten. Man begegnet ihr schon überall im Dampfkessel.\n\nVernichtet alles, das bereits befallen ist, und bringt mir das mittlere Zahnrad von Robogenieur Dampfhammer. Beeilt Euch!", sourceObjective = "Tötet 3 Sumpfoberanführer und 6 Aussätzige des Echsenkessels und erbeutet ein verstrahltes Zahnrad von Robogenieur Dampfhammer. Kehrt dann zu Naturalist Biss zurück.", progress = "Geht so sorgfältig wie möglich vor. Das Schicksal der Zangarmarschen hängt davon ab.", completion = "Ich bin froh, dass wir die Krankheit eingedämmt haben, bevor sie sich in den Zangarmarschen ausbreiten konnte. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[29615] = { id = 29615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windrufer Klaue und die Wasserdiebin", description = "Die Naga versuchen schon seit längerem, das Wasser aus den Zangarmarschen abzupumpen. Die Dampfkammer ist der Dreh- und Angelpunkt dieser Operation. Überwacht wird sie von Hydromantin Thespia.\n\nIhr Tod würde die Naga empfindlich treffen.", sourceObjective = "Tötet Hydromantin Thespia und kehrt zu Windrufer Klaue in der Dampfkammer zurück.", completion = "Vielleicht können wir dem Land das verzweifelt benötigte Wasser nun zurückgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29616] = { id = 29616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf die Dampfkammer", description = "Bisher ist es uns nicht gelungen, die Naga in der Dampfkammer, wo sich ihre Pumpenzentrale befindet, aufzuhalten.\n\nZum Glück versucht die Expedition, die ich ausgesandt habe, das zu ändern. Würdet Ihr Euch in die Dampfkammer begeben und Behüterin Jhang Eure Hilfe anbieten?", sourceObjective = "Sprecht mit Behüterin Jhang in der Dampfkammer.", completion = "Ich danke den Sternen für Euch! Wir benötigen Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29617] = { id = 29617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Tiankloster", description = "Aus ganz Pandaria sind Leute angereist, um sich im Tiankloster gleich nördlich von hier ausbilden zu lassen. Wahrscheinlich, weil sie niemanden abweisen. Sie kümmern sich um Jinyu, Ho-zen... oder selbst Auswärtige wie Euch!\n\nMeine Freundin, Lin, ist gerade erst vor ein paar Wochen im Kloster aufgenommen worden. Wenn Ihr mehr über die Ausbildung bei unseren Mönchen erfahren möchtet, solltet Ihr vielleicht mit ihr sprechen!", sourceObjective = "Sprecht mit Lin Zartpfote im Tiankloster im Jadewald.", completion = "Ihr seid in aufregenden Zeiten hier eingetroffen. Der Hohe Älteste Wolkensturz hat zugestimmt, eine neue Klasse Schüler im Kloster aufzunehmen. Dies könnte meine Chance sein, endlich zu lernen, wie man kämpft!", sourceObjectiveStatus = "unverified-source-field" }
quests[29618] = { id = 29618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hohe Älteste", description = "Wie außergewöhnlich, jemanden so fremdländisches wie Euch hier in unserem Tempel begrüßen zu dürfen, {class}. Seid Ihr an einer Ausbildung interessiert?\n\nIhr... Ihr seht sehr stark aus. Es sollte Euch keine Mühe machen, im Kloster aufgenommen zu werden. Vielleicht solltet Ihr mit dem Hohen Ältesten dort oben auf dem Balkon sprechen.", sourceObjective = "Sprecht mit dem Hohen Ältesten Wolkensturz im Tiankloster im Jadewald.", completion = "Willkommen im Tiankloster. Ich hörte, dass die junge Lin Euch schon von unserer Rolle hier in unserem Dorf in den Bergen unterrichtet hat.\n\nWir verfügen über nicht viel Erfahrung mit Fremden. Es wäre uns eine große Ehre, wenn Ihr Euch an der Seite unseres Nachwuchses ausbilden lassen wollt. Wir können Euch aber kaum etwas anbieten, {class}... außer vielleicht Wissen und das Verständnis dafür, was es heißt, ein Pandaren zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[29619] = { id = 29619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein höflicher Gast", description = "Ich habe es schon gehört! Der Hohe Älteste möchte, dass Ihr eine Ausbildung zusammen mit uns macht!\n\nFür uns Schüler wird es ein Bankett geben... Und Ihr solltet vielleicht ein Geschenk mitbringen, als Zeichen der Höflichkeit.\n\nDie Orangen im Hain südlich des Tempels sind gerade reif und sehr süß. Bringt einige davon mit zum Bankett.", sourceObjective = "Sammelt 8 reife Orangen im Orangenhain südlich des Tianklosters ein.", progress = "Seid Ihr bereit für das Bankett? Ich bin ja so aufgeregt.", completion = "Die sind perfekt. Was für ein tolles Geschenk, {name}!\n\nOh, ich? Ich bringe natürlich Bier mit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29620] = { id = 29620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das große Bankett", description = "Das Bankett sollte jetzt jeden Moment beginnen. Sucht den Hohen Ältesten auf und erweist ihm die Ehre. Ich werde direkt hinter Euch sein.", sourceObjective = "Sprecht mit dem Hohen Ältesten Wolkensturz im Bankettareal im Tiankloster.", progress = "Die Ausbildung wird noch früh genug beginnen, junger {class}. Aber zunächst müssen wir reden, trinken und essen.\n\nAllerdings imponiert mir Eure Disziplin.", completion = "Damit sind die Einführungen beendet. Ihr werdet jetzt bald mit Eurer Ausbildung beginnen können.\n\nAllerdings... könnt Ihr erst beginnen... NACHDEM wir noch einen Krug Bier getrunken haben. Oder vielleicht zwei, was meint Ihr, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[29622] = { id = 29622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beginn der Ausbildung", description = "<Xiao sieht nicht von seiner Schüssel auf.>\n\nHey, <neuer Schüler/neue Schülerin>! Schön, dass Ihr das Bankett überlebt habt! Übung 1: Bestanden!\n\n<Xiao isst geräuschvoll.>\n\nIhr solltet mit Ausbilder Xann sprechen. Er erwartet Euch sicher schon zu den täglichen Übungen.\n\n<Er isst weiter. Ihr vermutet, dass er Euch nichts weiter zu sagen hat.>", sourceObjective = "Meldet Euch bei Ausbilder Xann im Tiankloster im Jadewald.", completion = "Erst trinkt Ihr zu viel Bier und dann kommt Ihr zu spät zu den Übungen? Ihr scheint Euch ja schon an die Pandaren-Kultur gewöhnt zu haben.\n\nAlso fangen wir an.", sourceObjectiveStatus = "unverified-source-field" }
quests[29623] = { id = 29623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfektion", description = "Perfektion kann durch Wiederholung erlangt werden. Alle Schüler in der Ausbildungsarena da unten werden früher oder später die perfekten Formen finden... wenn sie nicht vorher aufgeben. Das ist eine Tatsache.\n\nIch möchte Euch empfehlen, sich ihnen anzuschließen, {name}. Als ein Ehrengast des Klosters seid Ihr schließlich nicht angehalten, die 10.000 Wiederholungen täglich auszuführen. Folgt einfach für ein paar Minuten den Beispielen derjenigen, die es vormachen.", sourceObjective = "Führt 12 Übungsschläge in der Ausbildungsarena des Klosters aus, indem Ihr die Beispiele nachahmt.", progress = "Auch ich habe einst in diesem Bereich meine Ausbildung gemacht. Damals war alles noch viel einfacher.", completion = "Ihr kämpft aber nicht zum ersten Mal, oder? Eure Formen sind nicht perfekt, aber durchaus geübt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29624] = { id = 29624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitte recht aufmerksam", description = "In Eurer nächsten Prüfung geht es um Konzentration und Aufmerksamkeit. Ich möchte, dass Ihr Eure Fähigkeiten an den Sandsäcken unten im Übungsbereich verfeinert.\n\nDie Säcke sind jeweils in Zweiergruppen aufgehängt. Wenn ich \"links\" rufe, greift Ihr den Sack auf der linken Seite an. Wenn ich \"rechts\" rufe, greift Ihr den Sack auf der rechten Seite an.\n\nWenn Ihr diesen einfachen Anweisungen nicht folgen könnt, wird die Aufgabe umso schwerer.\n\nUnd jetzt schlagt auf diese Säcke ein, bis sie platzen, {name}.", sourceObjective = "Zerstört 2 Sandsäcke. Folgt den Anweisungen von Ausbilder Xann, um zu entscheiden, welche Säcke angegriffen werden sollen.", progress = "Worauf wartet Ihr?", completion = "Ihr zählt vielleicht nicht zur regulären Schülerschaft hier, aber trotzdem könnt Ihr ja etwas lernen.\n\nIch versichere Euch, dass die Fähigkeit, schnell von einem Ziel zum anderen wechseln zu können, in zukünftigen Kämpfen von großem Wert sein kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[29626] = { id = 29626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klosterwart Wu", description = "Wir haben nicht viele Regeln hier, aber eine davon solltet Ihr Euch merken. Wer essen will...\n\n<Xiaos Magen knurrt vernehmlich.>\n\n...muss etwas dafür tun. Der Klosterwart Wu kann Euch Eure heutigen Arbeiten zuweisen. Er befindet sich auf dem Markt im Westen.", sourceObjective = "Meldet Euch bei Klosterwart Wu im Tiankloster im Jadewald.", completion = "<Wu spricht Euch kurz angebunden an.>\n\nIhr seid {name}, oder? Der Lieblingssohn des Hohen Ältesten? Ja, Ihr wart doch auch auf dem Bankett.\n\nAber ich werde Euch nicht bevorzugt behandeln, junger Herr. Ihr werdet hier genauso hart arbeiten wie alle anderen Pandaren-Schüler.\n\nVielleicht sogar noch härter.", sourceObjectiveStatus = "unverified-source-field" }
quests[29627] = { id = 29627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ordentliche Waffe", description = "Aber immer der Reihe nach.\n\nOrdentliche Schüler benötigen eine ordentliche Waffe. Und die vorbildlichen Schüler bauen sich ihre eigenen Waffen... oder sammeln zumindest die Materialien dafür selbst ein.\n\nDie in der Nähe wachsenden Ruten sollten eine gute Waffe ergeben. Und außerdem müsst Ihr noch Schwarznussextrakt kaufen, um das Holz zu behandeln. Und wo Ihr schon mal Einkaufen geht, könnt Ihr gleich etwas Bier mitnehmen, damit...\n\n<Wu hält inne.>\n\nAlso, Ihr wisst schon, was man mit Bier so macht.", sourceObjective = "Besorgt 6 Rattanruten aus der Gegend um den Markt vom Tiankloster.\n\nKauft eine Phiole Schwarznussextrakt von Juni Weißblüte.\n\nKauft 3 dreifach bittere Bräue von Braumeister Lei Kanglei.", progress = "<Wu schaut Euch erwartungsvoll an.>", completion = "<Klosterwart Wu nimmt dankbar die Materialien entgegen.>\n\nBis zum Ende Eurer Ausbildung werde ich Euch eine Waffe gefertigt haben. Und jetzt weiter mit der echten Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29628] = { id = 29628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein starker Rücken", description = "Einige unserer Schüler haben einen... enormen Appetit. Und manchmal haben wir Schwierigkeiten, genug Nahrung für alle bereitzustellen. In diesen Fällen müssen wir um Hilfe bitten.\n\nIn einem kleinen Haus im Nordwesten lebt eine freundliche, ältere Dame, die sich bereit erklärt hat, etwas Eintopf für unsere Schüler zu kochen. Ihr müsstet nur zu ihr gehen und ihn abholen.", sourceObjective = "Holt einen kochenden Kessel von Mutter Wu im Wachsgehölz ab und kehrt dann zu Klosterwart Wu im Tiankloster zurück.", progress = "Sie ist wirklich eine sehr nette Frau und eine sehr gute Köchin.\n\nDie beste Köchin der Welt, würde ich sagen.", completion = "Ich werde mich darum kümmern, dass der Eintopf gerecht unter den Schülern aufgeteilt wird.\n\nNachdem ich etwas für mich abgezweigt habe, versteht sich.", sourceObjectiveStatus = "unverified-source-field" }
quests[29629] = { id = 29629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine ruhige Hand", description = "Der Schwarznussextrakt, den Ihr von Juni Weißblüte gekauft habt, ist nur einer von vielen Extrakten, den wir hier für verschiedene Verwendungen bereit halten.\n\nRötelblattextrakt zum Beispiel kann man aus den Blumen in der Gegend vom Wachsgehölz im Westen gewinnen. Aus einer einzigen Blume erhält man mehrere Einheiten, aber man benötigt eine ruhige Hand, um der Blume den gesamten Extrakt zu entziehen.", sourceObjective = "Besorgt 80 Phiolen Rötelblattextrakt von den Rötelblattbüscheln im Wachsgehölz.", progress = "Die früheren Kräutermeister sollen in der Lage gewesen sein, 20 Phiolen Extrakt aus einer einzelnen Blume zu gewinnen.", completion = "Und nicht vergessen, die Hände zu waschen. Der Rötelblattsaft geht nie wieder ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[29630] = { id = 29630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und eine harte Faust", description = "Die Grünwaldgeister im Wachsgehölz westlich von hier stellen zwar keine unmittelbare Gefahr für uns dar, aber ihre Anzahl hat sich in letzter Zeit alarmierend erhöht - und damit auch ihre verschlagenen Possen.\n\nEs gehört zu unserer Pflicht als Hüter des Waldes, das Gleichgewicht zu wahren. Und Eure Pflicht ist es, diese Geister wieder zurück in die Erde zu befördern.", sourceObjective = "Erledigt 10 Grünholztrickster im Wachsgehölz.", completion = "Ich danke Euch, {name}. Die Geister werden sich in wenigen Tagen schon wieder vermehrt haben, aber zumindest im Augenblick ist das Gleichgewicht gewahrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29631] = { id = 29631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Feuereifer", description = "Kann ich Euch um einen Gefallen bitten, {name}?\n\nBevor ich in das Kloster kam, hatte ich keinerlei Erfahrung mit Kämpfen. Im Zuge meiner Ausbildung wurde ich zwar auch im Umgang mit Waffen geschult, aber niemals wirklich gefährlichen Situationen ausgesetzt. Aber jetzt bin ich nicht mehr in der Ausbildung, sondern ein voll bezahlter Wächter. Man erwartet von mir, dass ich das Gebiet um jeden Preis verteidige.\n\nMit den Grünwaldgeistern kann ich es aufnehmen, aber die Tiger im westlichen Wachsgehölz sind eine Nummer zu groß für mich. Könntet Ihr Euch vielleicht um sie kümmern?", sourceObjective = "Tötet 6 Wachsgehölztiger.", progress = "Bitte sagt niemanden etwas von unserer Vereinbarung. Meine Feigheit ist mir peinlich.", completion = "Ich danke Euch, {name}. Tausend Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[29632] = { id = 29632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereit zum Kampf", description = "Also, jetzt wollen wir doch mal sehen, aus welchem Holz Ihr geschnitzt seid.\n\nIhr trefft überall im Kloster auf Schüler. Fordert sie zu einem Kampf heraus. Bringt sie an ihre Grenzen. Ihnen wurde schließlich das gleiche aufgetragen wie Euch.\n\nEgal, ob Sieg oder Niederlage – aus dem Kampf gehen beide Kontrahenten gestärkt hervor.", sourceObjective = "Besiegt 8 Schüler von Tian in Übungskämpfen im Tiankloster.", progress = "In Eurer Heimat mögt Ihr zu den Helden zählen. Hier aber müsst Ihr Euch erst noch beweisen.", completion = "<Meister Steinfaust schaut Euch misstrauisch an.>\n\nAlso gut, ich habe genug gesehen. Schluss mit dem Verprügeln der jungen Schüler. Wir machen mit der nächsten Ausbildungsphase weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[29633] = { id = 29633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der wehrhafte Zhi-Zhi", description = "Auf den Hügeln rechts von mir findet Ihr einen Ho-zen namens Zhi-Zhi. Auch er hat genug Übungskämpfe gewonnen, um einen Rang aufzusteigen. Ich denke, er sollte eine größere Herausforderung für Euch darstellen.\n\nFordert ihn heraus und versucht, ihn zu besiegen.", sourceObjective = "Besiegt Zhi-Zhi im Tiankloster.", completion = "Offensichtlich muss ich Euch schon wieder einen Rang aufsteigen lassen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29634] = { id = 29634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der uralte Husshun", description = "Die Jinyu sind schon seit langer Zeit Verbündete der Pandaren und die Mitglieder ihres Volkes sind jederzeit in unserem Kloster willkommen. Husshun, einer ihrer erfahreneren Schamanen, ist einer unserer neuen Schüler.\n\nSeine Fähigkeiten als Mönch sind höchstens Mittelmaß, aber er ist dennoch ein starker Gegner. Er sollte die Herausforderung darstellen, nach der Ihr sucht.", sourceObjective = "Fordert Husshun im Tiankloster heraus und besiegt ihn.", completion = "Ich muss Euch warnen, {class}:\n\nWenn Ihr weiterhin meine besten Schüler besiegt, kann ich Euch nicht weiter unterrichten. Und dann habt Ihr keinen Grund mehr, meine Gesellschaft zu genießen.\n\nDenkt daran, bevor Ihr weiter mit solcher Geschwindigkeit meine anderen Schüler ausschaltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29635] = { id = 29635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der hungrige Xiao", description = "Meinen besten Schüler, Xiao, habt Ihr bereits am Tisch beim Bankett kennengelernt. Ich selbst hätte ihm schon längst seinen Abschluss gegeben, aber Ausbilder Xann besteht darauf, dass er noch mehr an seiner Disziplin arbeiten müsse.\n\nMeiner Meinung nach ist Disziplin vollkommen unwichtig, solange man alle seine Kämpfe gewinnt. Ich würde gern sehen, ob Xiao seine Siegesserie gegen Euch fortsetzen kann.", sourceObjective = "Fordert Xiao im Tiankloster heraus und besiegt ihn.", progress = "Dem jungen Xiao winkt eine große Zukunft als Kampfkünstler. Ich wünsche Euch viel Glück für Euren nächsten Kampf.", completion = "Ich kann nicht behaupten, dass ich überrascht bin, {race}. Ihr seid ein herausragender Kämpfer und ein exzellenter {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29636] = { id = 29636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein langer Weg", description = "Ich habe Euch alles gelehrt, was in meiner Macht steht, {name}. Jetzt ist es an der Zeit, dass Ihr Euch an die Ausbilderin Myang wendet.\n\nDie Kämpfe, die sie ausrichtet, sind weniger traditionell als meine. Aber der Weg von reisenden Abenteurern wie Euch ist unvorhersehbar und eine umfangreiche Kenntnis der verschiedenen Kampfstile könnte sich als großer Vorteil erweisen.\n\nLebt wohl, {name}, und viel Glück bei Eurer weiteren Ausbildung.", sourceObjective = "Meldet Euch bei Ausbilderin Myang im westlichen Bereich des Tianklosters.", completion = "Seid gegrüßt, {name}. Ihr habt Euch einen guten Ruf unter unseren Schülern hier erworben. Viele Eurer Übungspartner haben mir von Euch berichtet. Zumeist mit aufgeplatzten und geschwollenen Lippen.\n\nIch freue mich schon darauf, Euch zu betreuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29637] = { id = 29637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massenschlägerei", description = "Meister Steinfaust hat Euch gelehrt, wie Ihr gegen einen einzelnen Gegner bestehen könnt. Jetzt erlernt Ihr den Kampf gegen eine Gruppe von Gegnern.\n\nZum Beispiel gegen fünfzig.\n\nBegebt Euch in den Ring des Inneren Fokus da unten und entzündet das Feuerwerk, wenn Ihr bereit seid. Meine Helfer werden gemeinsam auf Euch losstürzen.\n\nVersucht, den Ansturm zu überleben.", sourceObjective = "Entzündet das Kloster-Feuerwerk im Ring des Inneren Fokus und überlebt die zwei Minuten dauernde Massenschlägerei.", progress = "Viel Glück, {name}.", completion = "Euer Kampfstil ist bemerkenswert, {name}. Die anderen Schüler könnten viel von Euch lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29639] = { id = 29639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Bravour bestanden", description = "Ihr habt alle Prüfungen bestanden, die wir Euch gestellt haben, {name}. Es ist an der Zeit, dass Ihr Euch jetzt um größere und wichtigere Angelegenheiten kümmert.\n\nAber zuvor gibt es noch ein Bankett! Der Hohe Älteste erwartet Euch im Bankettareal, um die Beendigung Eurer Klosterausbildung gebührend zu feiern.", sourceObjective = "Meldet Euch beim Hohen Ältesten Wolkensturz im Tiankloster im Jadewald.", completion = "Ich gratuliere Euch, {name}. Obwohl Ihr rein freiwillig an der Ausbildung teilgenommen habt, waren Eure Ergebnisse sehr beeindruckend. Ihr seid ein Vorbild für unsere jüngeren Schüler.\n\nDer Klosterwart Wu hat dies hier für Euch angefertigt. Ihr könnt darüber verfügen, wie es Euch beliebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29640] = { id = 29640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Spion To'gun", description = "Der Schattenrat hat die meisten unserer Spione bereits getötet, aber To'gun, der fliehen konnte, war so dumm zurückzukehren!\n\nIhr müsst ihn finden. Er ist unvernünftig, aber wir müssen herausfinden, was er weiß.", sourceObjective = "Findet Spion To'gun im Schattenlabyrinth von Auchindoun.", completion = "Wäret Ihr so nett, mir aus dem Käfig zu helfen? Er ist ein wenig beengt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29641] = { id = 29641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeleninstrumente", description = "Sie haben mich gefoltert, damit ich ihnen alles verrate, was ich weiß.\n\nDie anderen haben sie an Höllenschlund verfüttert, ich hätte als Nächstes dran sein sollen. Aber ich habe ihnen nichts verraten!\n\nSie benutzen spezielle Geräte, damit ihre Beschwörungen mächtiger werden. Diese Geräte müsst Ihr stehlen!", sourceObjective = "Stehlt 5 Seeleninstrumente und bringt sie zu Spionin Grik'tha im Schattenlabyrinth von Auchindoun.", progress = "Habt Ihr To'gun gefunden?", completion = "Dies sind also die Seeleninstrumente, mit denen der Schattenrat seine Beschwörungskraft erhöht? Interessant.", sourceObjectiveStatus = "unverified-source-field" }
quests[29642] = { id = 29642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in Auchindoun", description = "Meine Spione in Auchindoun haben uns erschreckende Berichte geschickt. Seit seiner Explosion vor ein paar Jahren hat dieser Ort nichts als Ärger gebracht.\n\nDort ist etwas - mal wieder - ganz schön schief gegangen, und der Schattenrat bereitet sich auf einen Krieg vor. Auch wenn die Berichte viele Details verschweigen, müssen sie sich auf einen Krieg im Inneren vorbereiten.\n\nIhr müsst Euch zum Eingang des Schattenlabyrinths begeben. Mein Feldkommandeur, Mahfuun, wird Euch genau erklären, was zu tun ist.", sourceObjective = "Meldet Euch bei Feldkommandeur Mahfuun im Schattenlabyrinth in Auchindoun in den Wäldern von Terokkar.", completion = "Wurde auch Zeit, dass Ihr eintrefft.\n\nMehlisah hat bereits vor Tagen angekündigt, dass sie Hilfe schicken würde. Und wir kämpfen hier noch länger!", sourceObjectiveStatus = "unverified-source-field" }
quests[29643] = { id = 29643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kodex des Blutes", description = "Vor zwei Jahren beschwor der Schattenrat ein Wesen, das eine Schneise der Verwüstung in Auchindoun hinterließ.\n\nLest den Kodex des Blutes, um herauszufinden, was damals geschah. Seid jedoch vorsichtig, denn Großmeister Vorpil beschützt ihn mit seinem Leben.", sourceObjective = "Lest den Kodex des Blutes im Schattenlabyrinth von Auchindoun.", completion = "Während Ihr den magiegeladenen Folianten öffnet, überkommt Euch ein Gefühl des Schreckens.\n\nIrgendetwas ist hier eindeutig nicht in Ordnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[29644] = { id = 29644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In das Herz des Labyrinths", description = "Der Schattenrat hat die Kontrolle über das kosmische Wesen, das sie vor fast zwei Jahren beschworen haben, verloren!\n\nMan nennt es Murmur und es droht, den Schattenrat zu überrennen und zu entkommen!", sourceObjective = "Vernichtet Murmur und meldet Euch danach bei Feldkommandeur Mahfuun im Schattenlabyrinth von Auchindoun.", completion = "Ich schüttele mich bei dem Gedanken, was hätte passieren können, wenn Murmur entkommen wäre.\n\nDanke, mutiger Held.", sourceObjectiveStatus = "unverified-source-field" }
quests[29645] = { id = 29645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschafter Höllenschlund", description = "Als die Kabale unsere Spione entdeckte, verfütterte sie alle an Botschafter Höllenschlund.\n\nUnsere Männer verdienen Gerechtigkeit. Tötet die Ritualisten, die Höllenschlund binden und vernichtet dann auch ihn.\n\nEr hat dieses Schicksal schon lange verdient.", sourceObjective = "Tötet 12 Ritualisten der Kabale sowie Botschafter Höllenschlund und kehrt zu Feldkommandeur Mahfuun im Schattenlabyrinth von Auchindoun zurück.", completion = "Das bringt zwar niemanden zurück, aber wenigstens wurde der Gerechtigkeit Genüge getan.", sourceObjectiveStatus = "unverified-source-field" }
quests[29646] = { id = 29646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Bravour bestanden", description = "So, ich habe Euch alles beigebracht, was ich konnte. Und die anderen offensichtlich auch.\n\nDer Hohe Älteste erwartet Euch im Bankettareal, um Euren Abschied gebührend zu feiern. Nicht, dass wir Euch gerne gehen lassen... Er feiert einfach gern.", sourceObjective = "Meldet Euch beim Hohen Ältesten Wolkensturz im Bankettareal im Jadewald.", completion = "Ich gratuliere Euch, {name}. Obwohl Ihr rein freiwillig an der Ausbildung teilgenommen habt, waren Eure Ergebnisse sehr beeindruckend. Ihr seid ein Vorbild für unsere jüngeren Schüler.\n\nDer Klosterwart Wu hat dies hier für Euch angefertigt. Ihr könnt darüber verfügen, wie es Euch beliebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29647] = { id = 29647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Bravour bestanden", description = "Die Krawallgrube war Eure letzte Herausforderung. Ihr habt alle Disziplinen gemeistert, die an dieser Schule gelehrt werden.\n\nEure Ausbildung begann mit einem Bankett und so soll sie auch enden. Der Hohe Älteste erwartet Euch im Bankettareal und ich werde gleich hinter Euch sein.", sourceObjective = "Meldet Euch beim Hohen Ältesten Wolkensturz im Bankettareal im Jadewald.", completion = "Ich gratuliere Euch, {name}. Obwohl Ihr rein freiwillig an der Ausbildung teilgenommen habt, waren Eure Ergebnisse sehr beeindruckend. Ihr seid ein Vorbild für unsere jüngeren Schüler.\n\nDer Klosterwart Wu hat dies hier für Euch angefertigt. Ihr könnt darüber verfügen, wie es Euch beliebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29649] = { id = 29649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man ein Leben rettet", description = "Gunny stirbt an einem mächtigen Fluch, {name}.\n\nGroßhexenmeister Nethekurse benutzt zwei mystische Kohlefeuer zur Verstärkung seiner Kräfte. Vielleicht könnten wir mit etwas Glut aus einem Kohlefeuer diese dunkle Magie rückgängig machen.", sourceObjective = "Vorhutsspäher Chadwick in den Zerschmetterten Hallen der Höllenfeuerzitadelle möchte, dass Ihr ihm Teufelsglut bringt.", progress = "Habt Ihr die Glut dabei? Wir haben nicht viel Zeit.", completion = "Er war ein guter Soldat.", sourceObjectiveStatus = "unverified-source-field" }
quests[29650] = { id = 29650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsglut", description = "Caza'rez stirbt wie ein Feigling.\n\nGroßhexenmeister Nethekurse hat ihn mit einem schrecklichen Fluch belegt. Bringt mir etwas Glut aus seinen Kohlenpfannen. Vielleicht können wir die Magie damit umkehren, bevor es zu spät ist.", sourceObjective = "Steingardist Stok'ton in den Zerschmetterten Hallen der Höllenfeuerzitadelle möchte, dass Ihr ihm Teufelsglut bringt.", progress = "Habt Ihr die Glut bekommen? Caza'rez verdient es, wie ein Krieger zu sterben.", completion = "Ich werde viele Lieder zu seinem Ruhm anstimmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29651] = { id = 29651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Sterbenden", description = "Ihre Elitekrieger sind gnadenlos... so... mächtig.\n\n<Caza'rez spuckt Blut.>\n\nIhr müsst sie töten... sonst werden wir Kargath nie besiegen...", sourceObjective = "Caza'rez in den Zerschmetterten Hallen der Höllenfeuerzitadelle möchte, dass Ihr 4 Legionäre der Zerschmetterten Hand, 2 Zenturionen der Zerschmetterten Hand und 2 Champions der Zerschmetterten Hand tötet.", completion = "Caza'rez ist... von uns gegangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29652] = { id = 29652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letzter Gefallen", description = "Der alte Gunny macht's nicht mehr lange...\n\nErweist mir einen letzten Gefallen und tötet die größten, übelsten Höllenorcs, die Ihr finden könnt.\n\nIm Andenken an alte Zeiten, ja?", sourceObjective = "Gunny in den Zerschmetterten Hallen der Höllenfeuerzitadelle möchte, dass Ihr 4 Legionäre, 2 Zenturionen und 2 Champions der Zerschmetterten Hand tötet.", completion = "Hätten wir ihn doch retten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[29653] = { id = 29653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wille des Kriegshäuptlings", description = "Kargath war einst einer der größten Helden der Horde.\n\nDoch nun trägt er den falschen Mantel des Kriegshäuptlings. Bringt mir die nach ihm benannte Waffe, damit wir uns an seine früheren Heldentaten erinnern können und nicht an die Gräuel, die er heute anrichtet.", sourceObjective = "Bringt Kriegshäuptling Kargaths Faust zu Steingardist Stok'ton in den Zerschmetterten Hallen der Höllenfeuerzitadelle.", progress = "Habt Ihr einen Beweis für den Sieg über Kargath Messerfaust?", completion = "Wir dürfen den Orc nicht vergessen, der Kargath einst war, noch die Lektion, die uns sein Fall sein sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[29654] = { id = 29654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal wenden", description = "Es gibt nur einen Weg, um sicherzustellen, dass die Höllenorcs die Ehrenfeste und die Allianz nicht länger bedrohen.\n\nIhr Kriegshäuptling muss sterben.\n\nBringt mir die Waffe, die nach ihm benannt ist, damit wir seinen Tod niemals vergessen.", sourceObjective = "Bringt Kriegshäuptling Kargaths Faust zu Vorhutsspäher Chadwick in den Zerschmetterten Hallen der Höllenfeuerzitadelle.", progress = "Habt Ihr einen Beweis für den Sieg über \"Kriegshäuptling\" Kargath Messerfaust mitgebracht?", completion = "Mit Eurer Hilfe haben wir dem Feind schweren Schaden zugefügt.\n\nDie Ehrenfeste war schon seit Jahren nicht mehr so sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[29655] = { id = 29655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ganz besonderes Tuch", description = "Kriegshetzer O'mrogg hat mehr mutige Soldaten auf dem Gewissen als jeder andere Feind, dem ich bisher begegnet bin. Er ist skrupellos, listig und äußerst mächtig.\n\nTötet ihn und bringt mir sein Kriegstuch. Wir werden ein Banner daraus nähen, sodass der Zorn der Horde für alle sichtbar ist.", sourceObjective = "Tötet Kriegshetzer O'mrogg und bringt sein Kriegstuch zu Steingardist Stok'ton in den Zerschmetterten Hallen der Höllenfeuerzitadelle.", progress = "Habt Ihr das Tuch dabei?", completion = "Sehr gut. Nun werden diese blutgierigen Ungeheuer sehen, mit wem sie sich angelegt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29656] = { id = 29656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "O'mroggs Kriegstuch", description = "Sturmwind möchte Beweise für unsere Kriegserfolge sehen.\n\nWir könnten ihm Leichensäcke schicken, aber ich denke, das Kriegstuch von O'mrogg, Kargaths mächtigstem Krieger würde ihn mehr beeindrucken. Traut Ihr ihn Euch zu?", sourceObjective = "Tötet Kriegshetzer O'mrogg und bringt sein Kriegstuch zu Vorhutsspäher Chadwick in den Zerschmetterten Hallen der Höllenfeuerzitadelle.", progress = "Habt Ihr das Tuch dabei?", completion = "Meine Vorgesetzten werden damit sehr zufrieden sein. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[29657] = { id = 29657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus großer Kraft folgt große Verantwortung", description = "<Ihr hört eine Stimme, leicht wie der Klang winziger Glocken, in Eurem Kopf.>\n\nIn der Mechanar entstehen durch die Technologie meines Volks Manazellen, Objekte, die eine gewaltige Energie in sich tragen.\n\nTötet Mechanolord Kapazitus, damit Kael'thas' Streitkräfte sich diese Macht nicht zu Nutze machen können.", sourceObjective = "A'dal bittet Euch, Mechanolord Kapazitus in der Mechanar der Festung der Stürme zu töten.", completion = "Beeindruckend, {name}. Doch es gibt noch viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[29658] = { id = 29658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kalkulator", description = "<Eine leichte Brise streicht über Euer Gesicht.>\n\nNur noch eines bleibt zu tun.\n\nPathaleon der Kalkulator überwacht die meisten Operationen seines Herrn. Er persönlich trägt die Verantwortung für einen Großteil des Leids, das in letzter Zeit über die Welt gekommen ist.\n\nIch möchte, dass Ihr ihn vernichtet.", sourceObjective = "A'dal hat Euch gebeten, Pathaleon den Kalkulator in der Mechanar der Festung der Stürme zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29659] = { id = 29659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlorene Schatz", description = "Ich spüre, dass eines der Artefakte meines Volkes gestohlen wurde und im Behälter der Legion aufbewahrt wird.\n\nSie dürfen nicht entdecken, wie mächtig es ist. Würdet Ihr die Torwächter töten und es wiederbeschaffen? Ich wäre Euch sehr dankbar.", sourceObjective = "Beschafft für A'dal den Blendenden Zorn aus dem Behälter der Legion in der Mechanar der Festung der Stürme.", sourceObjectiveStatus = "unverified-source-field" }
quests[29660] = { id = 29660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung der Botanika", description = "Kael'thas und seinen Streitkräften ist es nicht gelungen, die vielen Kreaturen in der Botanika niederzuwerfen. Wir müssen versuchen, ihre Fehler wiedergutzumachen.\n\nDer erste Schritt ist die Eliminierung ihrer Streitkräfte, damit sie keinen weiteren Ärger mehr verursachen können.", sourceObjective = "A'dal möchte, dass Ihr Kommandantin Sarannis, Hochbotaniker Freywinn und Dorngrin den Hüter in der Botanika der Festung der Stürme tötet.", completion = "Die Kreaturen an diesem Ort hätten sie früher oder später auch ohne unser Eingreifen getötet. Wir haben zum Besten aller gehandelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29661] = { id = 29661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lektion trockenen Fells", description = "Über die Meditation werde ich versuchen herauszufinden, wo sich Shu aufhält und wie wir dorthin gelangen können. In der Zwischenzeit könntet Ihr sicherlich von etwas Übung und Disziplin profitieren.\n\nEure erste Aufgabe wird diejenige sein, die allen Schülern, die sich in die Teiche begeben, zufällt: Findet einen Weg über die Balancierpfähle im Westen und läutet die Glocke, ohne in den Teich zu fallen.\n\nSolltet Ihr herunterfallen, wird der Fluch des Teichs es Euch erschweren, den Pfahl erneut zu erklimmen, sodass Ihr zum Ufer zurückkehren müsst, um von vorn zu beginnen.\n\nOh... und passt auf die Kraniche auf...", sourceObjective = "Findet einen Weg über die Balancierpfähle und läutet die Übungsglocke.", completion = "Gut. Ihr lernt schnell.", sourceObjectiveStatus = "unverified-source-field" }
quests[29662] = { id = 29662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Härter als Schilfrohre", description = "Besorgt mir etwas Schilfrohr von den Teichen ganz in der Nähe.\n\nFragt nicht warum. Tut es einfach, und lernt.", sourceObjective = "Sammelt 8 Stücke hartes Tränenholzschilf.", progress = "Euch meine Stärke zu schildern ist sinnlos. Ich muss sie Euch demonstrieren.", completion = "Gut.\n\nEs gibt kein einziges Schilfrohr, das meiner Kraft jemals widerstanden hätte.\n\nTretet zurück und lasst mich Eure Zweifel zerstreuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29663] = { id = 29663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lektion des balancierten Steines", description = "Ich benötige Ruhe, während ich meditiere. Übt Euch in Eurer Kampfkunst, während ich über Shus Aufenthaltsort nachsinne.\n\nAndere Mönche trainieren ihre Balance und Fähigkeiten im Kampf auf den Balancierpfählen in den umliegenden Teichen. Fordert sie heraus und besiegt sie.", sourceObjective = "Besiegt 6 Mönche der Tushui auf den Balancierpfählen.", completion = "Eure Fähigkeiten nehmen sichtlich zu. Euer Tritt wird sicherer. Eure Schläge sind kraftvoller.\n\nDisziplin und Übung sind die Schlüssel, um Euer Potenzial voll auszuschöpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29664] = { id = 29664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flammen des Herausforderers", description = "Ihr habt einen starken Geist und einen starken Willen, aber Euch fehlen die Fähigkeiten, um mir im Kampf gegenüberzutreten. Euer Körper muss den Kampf bestehen, aber in Wahrheit ist es Euer Charakter, der geprüft werden soll.\n\nLasst uns Chancengleichheit herstellen.\n\nNehmt diese Fackel, zündet sie im Kohlenbecken neben mir an und benutzt sie, um die drei erloschenen Kohlenbecken um den Teich herum anzuzünden.", sourceObjective = "Entzündet Eure unangezündete Herausfordererfackel am Kohlenbecken der flackernden Flamme und benutzt sie dann, um die 3 Kohlenbecken in der Nähe von Meister Li Fei anzuzünden.", completion = "Diese Feuer werden Euch die Stärke verleihen, die Ihr noch nicht erlangt habt. Sie werden Euer wahres Potenzial erhellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29665] = { id = 29665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Regen in die Traufe", description = "Nachdem ihr Schiff abgestürzt war, begannen finstere Kreaturen, aus dem Meer emporzusteigen und das Wrack zu durchforsten. Bei all dem Unglück, das ihnen heute widerfahren ist, wird unsere Hilfe womöglich nur ein Tropfen auf den heißen Stein sein.\n\nDennoch - diese Leute benötigen dringend unsere Hilfe. Bezwingt ihre Peiniger!", sourceObjective = "Bezwingt 8 Peiniger der Tiefenschuppen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29666] = { id = 29666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine knifflige Lektion", description = "In den Teichen lauern Gefahren. Die jüngste und wildeste davon sind die Wasserkneifer. Es ist an der Zeit, ihre Zahl auszudünnen, aber ich bin dazu nicht mehr imstande.\n\nFalls Ihr ein paar der Wasserkneifer beseitigen könntet, wäre ich Euch zu Dank verpflichtet. Passt aber auf ihre Anzahl auf - manchmal ist es besser, sie aus den Teichen herauszulocken, als geradewegs hineinzustapfen.", sourceObjective = "Tötet 6 Wasserkneifer.", completion = "Die Wasserkneifer sind merkwürdige Kreaturen. Es scheint sie zu stillen Gewässern hinzuziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29667] = { id = 29667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausdünnung der Herde", description = "Anscheinend haben Kael'thas' Streitkräfte die Wesen der Botanika bis zur Unkenntlichkeit verändert. Ich will nicht, dass sie auf die Scherbenwelt losgelassen werden, wie so viele vor ihnen.\n\nEines dieser Wesen heißt Laj. Ihn würde ich gern untersuchen, denn er scheint irgendwie anders zu sein. Vielleicht können wir etwas von ihm lernen.", sourceObjective = "A'dal bittet Euch, 6 mutierte Fleischpeitscher, 6 mutierte Furchtkreischer und 6 mutierte Schrecken zu töten und einen schnellentwickelnden Wedel von Laj in der Botanika der Festung der Stürme zu erbeuten.", progress = "Wie ich sehe, habt Ihr den Wedel erbeutet. Sehr gut.", completion = "Ihr habt Euch tapfer geschlagen, {name}. Allerdings muss ich Euch noch um die Erfüllung einer letzten Aufgabe bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29669] = { id = 29669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine äußerst traurige Aufgabe", description = "Ich muss Euch leider mit einer äußerst traurigen Aufgabe betrauen.\n\nWarpzweig war einmal der Wächter der ganzen Botanika. Doch nun ist er unrein und muss beseitigt werden.", sourceObjective = "A'dal bittet Euch, Warpzweig in der Botanika in der Festung der Stürme zu töten.", completion = "Als er noch lebte, war er ein stattlicher Wächter. Wir werden ihn vermissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29670] = { id = 29670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet Gormal", description = "Dank Euch versteckt sich eine aus Bauern bestehende Bürgerwehr in der Nähe. Hanae sagte etwas davon, ihnen \"flüssigen Mut\" zukommen zu lassen. Ich bin mir ziemlich sicher, dass sie jetzt betrunken und ZORNIG sind.\n\nDie Mogu glauben, sie könnten uns einfach überrollen - wir werden ihnen einen Kampf liefern, der ihnen die Augen öffnen wird.\n\nFolgt ihrer Spur durch die Ruinen und runter an den Strand. Findet ihren Anführer. Wenn Ihr ihn angreift, kommen wir dazu, um Euch zu helfen.", sourceObjective = "Tötet Unterwerfer Gormal im Lager Gormal.", completion = "Das ist äußerst beunruhigend. Wenn sich die Mogu so wie hier auf dem ganzen Kontinent zusammenschließen, würde dies eine ernste Bedrohung für Pandaria darstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29674] = { id = 29674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbändige Dunkelheit", description = "<Ihr hört klagendes Geläut in Eurem Kopf.>\n\nWir haben die gefährlichsten Wesen, die uns auf unseren Reisen untergekommen sind, eingesperrt.\n\nZereketh ist ein mächtiger Leerenfürst. Wenn es ihm gelingt, in den Nethersturm zu entkommen, wird er die reichlich vorhandene Leerenenergie in sich aufsaugen.", sourceObjective = "A'dal hat Euch gebeten, Zereketh den Unabhängigen in der Arcatraz der Festung der Stürme zu töten.", completion = "Die Wesen der Leere sind von Natur aus chaotisch. Als Bestandteil des Universums sind sie notwendig, doch sie müssen stets unter der Kontrolle des Lichts stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29675] = { id = 29675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn und Verdammnis", description = "Zornseher Soccothrates und Dalliah die Verdammnisverkünderin sind zwei mächtige Agenten der Brennenden Legion. Sie haben damit begonnen, Dämonen um sich zu versammeln.\n\nNoch ist die Armee klein, aber Ihr dürft nicht zulassen, dasss sie größer wird, sonst wird die Arcatraz bald zu einem weiteren Stützpunkt der Legion werden.", sourceObjective = "A'dal bittet Euch, Zornseher Soccothrates und Dalliah die Verdammnisverkünderin in der Arcatraz der Festung der Stürme zu töten.", completion = "Der Legion geht es nur ums Verschlingen. Das Gleichgewicht der Kräfte interessiert sie nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29676] = { id = 29676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen alten Freund finden", description = "Wie es scheint, hatte Shu, der Geist des Wassers, einen Spielgefährten, als er über die Jahre die Teiche besuchte. Es handelt sich um einen alten Pandaren, den wir den alten Liang nennen.\n\nLiang ist von der Hauptstadt fortgezogen und geht in den Teichen schon lange nicht mehr seinen Übungen nach. Man sagte mir, dass er in einem kleinen Haus nordöstlich von hier lebt, oben auf dem Hügel.\n\nLiang weiß vielleicht, was Shu vertrieben hat und wo wir den Geist finden könnten.\n\nGeht zu Liang und fragt nach Shu.", sourceObjective = "Sprecht mit dem alten Liang bei Liangs Refugium an den Singenden Teichen.", completion = "Besucher sind hier oben eine Seltenheit, aber Ihr seid willkommen. Es ist schön, Eure Bekanntschaft zu machen, junger {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29677] = { id = 29677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sonnenperle", description = "Shu, der Geist des Wassers, ist ewig jung, genau wie alle anderen Geister Shen-zin Sus. Ich bin mein ganzes Leben lang mit Shu befreundet gewesen, aber ich bin nicht mehr in der Lage, mit ihm zu spielen. Ich bin alt und habe schlicht keine Kraft mehr.\n\nBei all seiner Vielschichtigkeit ist Shu im Grunde einfach zufriedenzustellen: Er sehnt sich nach Freundschaft. Immer wenn ich zurückgekehrt bin, um mit Shu zu spielen, habe ich ihm eine Sonnenperle als Geschenk mitgebracht. Dann haben wir miteinander gespielt. In den Teichen im Südosten könnt Ihr eine Sonnenperle finden. Wer weiß, vielleicht werdet Ihr ja <sein neuer Freund/seine neue Freundin>...", sourceObjective = "Findet die Sonnenperle.", progress = "Die Entscheidung, nicht mehr zu den Teichen zurückzukehren, war eine schwere. Ich glaube, dass Shu sie nie wirklich verstanden hat. Er weiß nicht, wie es ist, alt und gebrechlich zu werden.", completion = "Shus Bedürfnisse sind den unseren nicht ganz unähnlich. Er möchte nicht allein sein - ungewollt, ungeliebt. Er sehnt sich danach, gebraucht zu werden und sein Leben mit anderen zu teilen.\n\nJetzt, wo Ihr dies wisst, sollte Euch klar sein, dass es nicht schwer sein sollte, sein Vertrauen zu gewinnen. Er sehnt sich einfach nur nach etwas Gesellschaft.", sourceObjectiveStatus = "unverified-source-field" }
quests[29678] = { id = 29678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shu, der Geist des Wassers", description = "Shu, der Geist des Wassers, schmollt im tiefen Teich nördlich von hier vor sich hin. Überquert die Felsen und lasst dann die Sonnenperle in die Mitte des Teichs fallen. Er wird wissen, was das bedeutet.", sourceObjective = "Überredet Shu, den Geist des Wassers, zu einem Spielchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29679] = { id = 29679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Freund", description = "Er möchte, dass Ihr mit ihm spielt. Worauf wartet Ihr?", sourceObjective = "Wasserwandelt in 5 von Shus Wasserfontänen.", completion = "Ich muss schon zugeben, das sah von hier aus ziemlich lustig aus.\n\nUnd wie es aussieht, habt Ihr einen neuen Freund gewonnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29680] = { id = 29680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Lebensgrundlage", description = "Wir haben getan, was Meister Shang von uns verlangt hat. Ich werde zum Tempel zurückkehren und ihm von unserem Fortschritt berichten. Ihr solltet Euch nach Süden begeben, um Wugou, den Geist der Erde, aufzusuchen.\n\nJi erwartet Euch am Dai-Lo-Bauernhof und wird sicherlich Eure Hilfe benötigen. Ich muss Euch warnen - Ji kann in all seiner Direktheit sehr unbedacht agieren. Erinnert Euch stets an das, was ich Euch gelehrt habe: Disziplin und Geduld.", sourceObjective = "Sprecht mit Ji auf dem Dai-Lo-Bauernhof. Ein Karren wartet nahe der Straße, um Euch dorthin zu bringen.", completion = "{name}! Ich hatte mich gefragt, wann wir uns wohl wiedersehen würden.\n\nNun, die gute Nachricht ist, dass Wugou, der Geist der Erde, ziemlich einfach zu finden war. Die schlechte ist, dass er einen wirklich tiefen Schlaf hat. Er wird wohl mit einem ziemlich steifen Nacken aufwachen nach all dem Geschiebe und Getrete, mit dem ich ihn schon zu wecken versucht habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29681] = { id = 29681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbruch aus dem Hochsicherheitstrakt", description = "Herold Horizontiss stellt das größte Problem in der Arcatraz dar.\n\nEr hat Aufseher Mellichar korrumpiert und dafür gesorgt, dass er zahlreiche Gefangene entlässt. Es ist nur eine Frage der Zeit, bis auch der Herold selbst freigelassen wird.\n\n{name}, Ihr dürft einen Diener der Alten Götter nicht am Leben lassen!", sourceObjective = "A'dal hat Euch gebeten, Herold Horizontiss in der Arcatraz der Festung der Stürme zu töten.", completion = "Danke, {name}. Mit Euren Taten habt Ihr zahllose Tragödien verhindert.", sourceObjectiveStatus = "unverified-source-field" }
quests[29682] = { id = 29682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrasse der Magister", description = "Vor kurzem haben wir eine Expedition zur Terrasse der Magister geschickt, um die Streitkräfte der Legion aufzuhalten.\n\nAllerdings haben wir seitdem nichts mehr gehört, und ich befürchte das Schlimmste.\n\nWürdet Ihr dorthin gehen und versuchen, Exarch Larethor zu finden? Er leitet die Expedition.", sourceObjective = "Hauptmann Theris Morgenheim möchte, dass Ihr Exarch Larethor in der Terrasse der Magister findet.", completion = "Morgenheim hielt uns für tot? Ha!\n\nIch habe ihm keinen Bericht geschickt, weil wir noch nicht weiter als bis zu diesem Punkt gekommen sind.\n\nVielleicht können wir das ja mit Eurer Hilfe ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[29684] = { id = 29684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgerissene Kommunikation", description = "Wir haben vor einiger Zeit einen Kontaktmann in der Terrasse der Magister eingeschleust, der für uns Informationen sammelt, aber der Kontakt zu ihm ist abgerissen.\n\nSein Wissen ist für unsere Mission essentiell.", sourceObjective = "Exarch Larethor in der Terrasse der Magister möchte, dass Ihr den Bluelfenspion Tyrith findet.", completion = "...kommt näher, {race}... Hört mir aufmerksam zu...", sourceObjectiveStatus = "unverified-source-field" }
quests[29685] = { id = 29685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht totzukriegen", description = "Wie Ihr mittlerweile wisst, arbeiten die Streitkräfte der Legion unermüdlich daran, die Kräfte des Sonnenbrunnens zu manipulieren, um so ihre eigenen unholden Machenschaften zu verwirklichen.\n\nKael'thas ist aus der Asche der Niederlage auferstanden und ist einmal mehr zu ihrem Anführer geworden. Er muss aufgehalten werden.", sourceObjective = "Kalecgos hat Euch damit beauftragt, Kael'thas in der Terrasse der Magister zu bezwingen. Ihr sollt Euch mit Kaels Kopf bei Larethor in der Terrasse der Magister melden.", progress = "Nun ja, {class}, ich muss gestehen, dass ich mir nicht sicher war, ob ich Euch jemals wiedersehen würde.", completion = "<Larethor hört aufmerksam zu, als Ihr von Euren Heldentaten in der Terrasse der Magister berichtet.>\n\nMan wird Tyrith vermissen. Er war ein guter Mann. Dank Euch war sein Tod nicht umsonst.", sourceObjectiveStatus = "unverified-source-field" }
quests[29686] = { id = 29686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine radikale Idee", description = "Wir können es uns nicht leisten, diesen Krieg zu verlieren. Ich möchte unsere Wachen stärken, damit mutige Männer und Frauen nicht sterben müssen.\n\nDer Legion ist ein mächtiges Elementarwesen in die Klauen gefallen. Seine Essenz könnte genau das sein, was wir brauchen.", sourceObjective = "Exarch Larethor auf der Terrasse der Magister bittet Euch, Vexallus zu töten und seine Essenz an Euch zu bringen.", progress = "Habt Ihr seine Essenz bekommen?", completion = "Hervorragend! Ich freue mich darauf, dieses Projekt meinen Vorgesetzten zu zeigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29687] = { id = 29687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Allianzen", description = "Die Legion arbeitet immer enger mit Kael'thas' Streitkräften zusammen. Das bereitet mir große Sorgen.\n\nSoweit wir wissen, sind vor allem Selin Feuerherz und Priesterin Delrissa mit der Vereinigung der beiden Armeen beschäftigt. Ihr müsst sie aufhalten.", sourceObjective = "Exarch Larethor in der Terrasse der Magister möchte, dass Ihr Selin Feuerherz und Priesterin Delrissa tötet.", completion = "Gut gemacht, Soldat. Ein Schritt nach dem anderen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29688] = { id = 29688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortführung der Kampagne", description = "Ich höre meistens zu, {class}. Ich höre zu, damit es der Kriegshäuptling nicht muss.\n\nIch habe gehört, wie es um unsere Kampagne gegen die Höllenfeuerzitadelle steht. Die Zeit zur Eroberung der Zerschmetterten Hallen, dem Machtzentrum der Höllenorcs, ist gekommen.\n\nSprecht mit Steingardist Stok'ton. Ihm unterstehen die Truppen dort.", sourceObjective = "Schattenjäger Ty'jin hat Euch gebeten, mit Steingardist Stok'ton in den Zerschmetterten Hallen der Höllenfeuerzitadelle zu sprechen.", completion = "Zieht den Kopf ein, sonst könnte er mit der falschen Seite eines Pfeils Bekanntschaft machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29689] = { id = 29689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortführung der Kampagne", description = "Die Zeit ist reif für einen letzten Schlag gegen die Höllenorcs.\n\nVorhutsspäher Chadwick erwartet Euch in den Zerschmetterten Hallen der Höllenfeuerzitadelle. Beeilt Euch, ihre Streitkräfte können jeden Moment die Ehrenfeste angreifen!", sourceObjective = "Truppenkommandant Danath Trollbann hat Euch gebeten, mit Vorhutsspäher Chadwick in den Zerschmetterten Hallen der Höllenfeuerzitadelle zu sprechen.", completion = "Seid still! Wenn sie uns jetzt bemerken, werden sie uns überrennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29690] = { id = 29690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Nebel", description = "<Nazgrim füllt seine Lunge mit Seeluft.>\n\nRiecht Ihr das, {name}? Das ist der Geruch unserer Heimat; jenes Landes, für das unsere Leute geblutet und ihr Leben hingegeben haben.\n\nUnd horcht... Hört Ihr das? Das ist der Klang von Frieden und Sicherheit - von jener Zuflucht, die wir uns geschaffen haben und der sich unsere Feinde nicht zu nähern wagen.\n\nMerkt Euch diese Eindrücke, denn so bald werdet Ihr sie nicht wieder genießen. Es gilt, einen Krieg zu gewinnen.\n\nNun geht und macht Euch bereit. Wir brechen auf!", sourceObjective = "Sprecht mit General Nazgrim auf Höllschreis Faust.", completion = "{name}!?\n\nSie hatten mir berichtet, dass Ihr gefallen seid...\n\nEs freut mich zu sehen, dass dem nicht so war. Es gilt Allianztruppen zu töten!", sourceObjectiveStatus = "unverified-source-field" }
quests[29691] = { id = 29691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt mir ein Gebüsch!", description = "Wir benutzen Bluthibiskus für viele Zwecke.\n\nNatürlich kommt er nur im Tiefensumpf vor und zahlreiche Bewohner haben Gefallen daran gefunden.\n\nIch wäre Euch sehr dankbar, wenn Ihr mir etwas davon bringen würdet.", sourceObjective = "Sammelt 5 Bluthibisken und kehrt zu T'shu im Tiefensumpf zurück.", progress = "Habt Ihr Hibiskus gefunden?", completion = "Sehr gut, aber wir können immer etwas davon gebrauchen. Vielleicht verschlägt es Euch ja bald noch einmal in den Tiefensumpf?", sourceObjectiveStatus = "unverified-source-field" }
quests[29692] = { id = 29692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt mir ein weiteres Gebüsch!", progress = "Wir könnten noch mehr Bluthibiskus gebrauchen. Ständig sind wir auf der Suche danach.\n\nBringt sie mir in Fünferbündeln, dann werde ich mich erkenntlich zeigen.", completion = "Sehr gut, aber wir können immer etwas davon gebrauchen. Vielleicht verschlägt es Euch ja bald noch einmal in den Tiefensumpf?" }
quests[29693] = { id = 29693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Axt des Generals", description = "Als Ihr langsam wieder zu Bewusstsein kommt und beginnt, Eure Umgebung wahrzunehmen, fällt Euch dieses Objekt unter den herumliegenden Wrackteilen auf.\n\nEuch dämmert, dass dies das erste Mal ist, dass Ihr Nazgrims Axt nicht in seinen Händen seht. Irgendwie macht das Eure knifflige Lage nur noch schlimmer...\n\nIhr wisst, dass der General seine Waffe wiederhaben wollen würde, sei er nun tot oder lebendig.", sourceObjective = "Bringt General Nazgrim seine Axt.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[29694] = { id = 29694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neu formieren!", description = "Sie haben eine Luftbasis! Diesen Allianzkapitän habe ich zum letzten Mal unterschätzt. So viele gute Krieger haben ihre Leben lassen müssen...\n\nEs muss ein paar Überlebende gegeben haben, die vor dem Absturz abspringen konnten. Wir brauchen alle fähigen Kämpfer, die wir bekommen können.\n\nFindet dort unten im Wald so viele Überlebende wie möglich, während ich das Wrack selbst durchsuche. Versammelt alle im nahegelegenen Dorf, damit wir zum Gegenschlag ausholen können.", sourceObjective = "Rettet Schattenmeisterin Kiryn, Nieti Kuppelplopp, Shokia und Unteroffizier Gorrok aus der Honigtaulichtung.", completion = "Das sind alle Überlebenden, {name}?\n\nSo sei es. Wir werden mit dem Blatt spielen, das das Schicksal uns zuteilt.\n\n\n\nVerdammt seien ihre Zahlen. So werden Helden gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29696] = { id = 29696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine Sterne!", description = "Einige von Kiryns Habseligkeiten wurden von Waldgeistern in der Gegend verteilt, aber dieser Gegenstand scheint Euch wichtig zu sein.\n\nDie Tasche hing einst an ihrer Taille und war gefüllt mit Wurfsternen. Ohne sie hat sie deutlich weniger Waffen zur Verfügung.\n\nWenn Ihr die Waffen von den Plagegeistern zurückholt, die in dieser Gegend hausen, würde Euch das sicherlich helfen.", sourceObjective = "Sammelt 100 von Kiryns Wurfsternen von verschlagenen Waldgeistern.", sourceObjectiveStatus = "unverified-source-field" }
quests[29715] = { id = 29715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hexe im Wald", description = "Oh bitte, {race}! Könnt Ihr mir helfen?\n\nEinige der Dorfkinder haben im Wald gespielt und sind nicht zurückgekehrt. Könntet Ihr bitte nach ihnen Ausschau halten, wenn Ihr dort hingeht?\n\nIch habe diesen Dorfrackern ausdrücklich gesagt, sie sollen die alte Witwe dort im Wald in Ruhe lassen. Ich vermute, dass sie sie wahrscheinlich belästigen. Sie glauben, dass sie eine Hexe ist.", sourceObjective = "Findet An Windpelz an der Straße nördlich der Hütte der Jadehexe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29716] = { id = 29716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die doppelte Ho-zen-Mutprobe", description = "In den Wäldern gibt es eine Hexe, aber niemand glaubt mir. Sie hat meinen Freund Shin in Jade verwandelt!\n\nWir hatten alle solche Angst und versuchten, nach Hause zu rennen, aber sie hat ihre großen Jademonster hinter uns hergeschickt. Ein paar von meinen Freunden versuchten, ihnen zu entkommen, indem sie auf Bäume kletterten.\n\nKönnt Ihr mir helfen, meine Freunde zu retten?", sourceObjective = "Rettet 6 verängstigte Pandarenkinder.", completion = "Oh, vielen Dank, dass Ihr geholfen habt, meine Freunde zu finden. Ich sehe Shin aber immer noch nicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[29717] = { id = 29717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braves Kätzchen!", description = "Ich habe versucht, einen der Jadetiger in den Wäldern zu bekämpfen, aber ich hatte zu viel Angst. Wenn sie einen anstarren, verwandelt man sich in eine Jadestatue!\n\nWirklich wahr! Ni, die Freundin von Chens Schwester, hat es von Kais Mutter erfahren.\n\nIch möchte auch so mutig sein wie Ihr. Könnt Ihr mir zeigen, wie man diese Jadetiger bekämpft?", sourceObjective = "Vernichtet 8 Jadewächter.", progress = "Unglaublich! Ihr seid aber wirklich mutig!", completion = "Das war ja unglaublich! Ihr habt denen so *WUMM* eine reingehauen und die nur so *AAHHH* und schon waren die hin!", sourceObjectiveStatus = "unverified-source-field" }
quests[29722] = { id = 29722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lektion in Sachen Mut", description = "Könntet Ihr mir beibringen, auch so tapfer zu sein wie Ihr?\n\nAls wir der Hexe einen Streich gespielt haben, haben wir ein paar blättrige Trickster verärgert. Ich glaube, die Hexe hat irgendetwas mit ihnen angestellt.\n\nKönntet Ihr mir zeigen, wie man gegen die ankommt?", sourceObjective = "Besiegt 8 blättrige Trickster südlich der Hütte der Jadehexe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29723] = { id = 29723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jadehexe", description = "Ich glaube, die Jadehexe hält Shin immer noch gefangen.\n\nAber ich... Ich kann das nicht! Ich trau' mich nicht, zu der Hexe zu gehen. Könntet Ihr vielleicht mit ihr sprechen und nachsehen, ob sie Shin immer noch gefangen hält? Ihr seid doch schon erwachsen. Ich glaube, Euch würde sie nicht in Jade verwandeln.", sourceObjective = "Besiegt die Jadehexe.", completion = "Hurra! Ich danke Euch! Shin ist gerettet und Ihr habt die alte Hexe besiegt! Und das Beste ist, dass unsere Eltern nie erfahren werden, was wir gemacht haben. Hurra!\n\nIrgendwie scheinen alle, die zurückgekommen sind, zu versuchen, ihre ganze Jade loszuwerden. Toya hat alles gesammelt und gesagt, dass Ihr mit ihm sprechen sollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29725] = { id = 29725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7 Bericht: Feuer vom Himmel", description = "Ja, wir haben Amber gefunden und sie ist am Leben und so. Aber das sind auch schon die einzigen guten Nachrichten.\n\nIch versuche mal, da weiterzumachen, wo der gute alte Rell aufhören musste...", sourceObjective = "Hört Euch Sullys Bericht an.", completion = "So, jetzt wisst Ihr, was mit dem guten alten Rell passiert ist.\n\n<Ihr bemerkt eine Änderung in Sullys Mimik und er wendet sich plötzlich ab. Ist es möglich, dass er... weint?>", sourceObjectiveStatus = "unverified-source-field" }
quests[29726] = { id = 29726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7 Bericht: Feindliche Eingeborene", description = "Ich... Ich kann Euch sagen, was als Nächstes passiert ist! Wir waren auf dem Weg nach Norden, in den Wald...", sourceObjective = "Hört Euch Klein-Lus Bericht an.", completion = "Glücklicherweise haben wir alle überlebt.\n\nNa ja... bis auf Söckchen...", sourceObjectiveStatus = "unverified-source-field" }
quests[29727] = { id = 29727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7 Bericht: Keine Gefangenen", description = "Die letzte Etappe unserer Reise brachte uns in den Westen, wo es ein großes Ho-zen-Dorf gibt. Wir hatten ein kleines Lager aufgeschlagen, außerhalb ihrer Sichtweite...", sourceObjective = "Hört Euch Amber Kearnens Bericht an.", completion = "Und so war's. Wir konnten den Weißen Bauern nicht finden, aber wir haben Geheiminformationen erhalten, die für die Allianz vielleicht noch viel wichtiger sind.\n\nDie Horde hat sich mit den Ho-zen verbündet und stattet sie aktuell gerade mit Waffen aus. Zusammen mit ihrer Affenarmee sind sie uns gegenüber dreißigfach in der Überzahl.", sourceObjectiveStatus = "unverified-source-field" }
quests[29728] = { id = 29728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweismittelvernichtung", description = "Ich muss Euch um einen weiteren Einsatz bitten, {name}.\n\nWir dürfen nicht zulassen, dass die persönlichen Dinge auf diesem Schiff in die falschen Hände fallen. Wir müssen es zerstören.\n\nAus den Überresten, die Ihr mir gebracht habt, habe ich ein paar improvisierte Sprengladungen zusammengestellt.\n\nBitte platziert diese Ladungen an einer beliebigen Stelle am Schiff. Aber achtet darauf, sie nicht zu dicht zusammenzulegen.\n\nSie sind ein wenig... öh... instabil. Im Falle einer vorzeitigen Explosion sollten sie also besser etwas verteilt sein.", sourceObjective = "Platziert 4 improvisierte Sprengladungen in der Nähe des Wracks der Herold. Die improvisierten Sprengladungen müssen mindestens 10 Meter voneinander entfernt liegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29730] = { id = 29730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späherbericht: Feindliche Eingeborene", description = "Ich glaub', ich kenne Eure erste Frage: \"Was zum Fiddel ist mit Unteroffizier Gorrok passiert?\" Aber keine Sorge. Der ist total am Leben. Gar nicht tot oder so.\n\n<Riko rutscht nervös hin und her.>\n\nAlso, wir GLAUBEN zumindest, dass er lebt. Aber er KÖNNTE AUCH ganz schön tot sein.\n\n<Riko schaut Euch erwartungsvoll an.>\n\nAlso gut! Ich werde Euch genau erzählen, was passiert ist.", sourceObjective = "Hört Euch Rikos Bericht an.", progress = "Ich bin noch nicht fertig, verfiddelt nochmal!", completion = "So, wie Ihr also seht, trifft Riko keine Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[29731] = { id = 29731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späherbericht: Auf der richtigen Fährte", description = "Das MEISTE, von dem, was Riko erzählt hat, ist wahr.\n\nWir haben uns nicht getraut, Gorrok zu verfolgen - die Horde verfügt nicht über ausreichend Truppen. Wir können auch nur eine bestimmte Anzahl Verluste kompensieren und ehrlich gesagt weiß ich nicht, wie mächtig diese Hexe ist.\n\nIch erzähle von da weiter, wo der Ho-zen aufgehört hat...", sourceObjective = "Hört Euch Kiryns Bericht an.", completion = "Und so haben wir unseren Allianzgefangenen gefunden.\n\nAber es ist noch viel mehr passiert. Noch sehr viel mehr...", sourceObjectiveStatus = "unverified-source-field" }
quests[29732] = { id = 29732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was runtergeht, muss wieder rauf!", description = "Nieti hat etwas hinterlassen, was sehr wichtig zu sein scheint. Auf dem Schaft steht \"Goblindrohnenspender\".\n\nNach einer kleinen Kalibrierung kann das Gerät Drohnen ins Basislager von Nazgrim entsenden.\n\nSo weit, so gut...\n\nEs gibt nur ein Problem: Die einzigen Vorratskisten, die einen Transport wert wären, sind nach dem Aufprall von der Klippe gefallen.\n\nAls Ihr darüber nachdenkt, seht Ihr im Augenwinkel den langen, zusammengerollten Schwanz eines vorbeifliegenden Klippengleiters...", sourceObjective = "Benutzt den Goblindrohnenspender an der Freigelegten Wurzel, um Vorräte zu bergen.\n\nHINWEIS: Für jede Benutzung ist ein Klippengleiterschwanz erforderlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[29733] = { id = 29733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7 Bericht: Verloren im Wald", description = "<Rell hustet schwer, bevor er spricht.>\n\nIch bitte Euch, {name}. Ihr müsst Euch anhören, was wir durchgemacht haben.\n\nDie gesamte verdammte Allianz sollte sich anhören, was wir durchgemacht haben. Es bleibt vielleicht nicht mehr viel Zeit.", sourceObjective = "Hört Euch Rells Bericht an.", completion = "...und so <hust> fanden wir...\n\n<Rells Erzählung wird von einem Hustenanfall unterbrochen. Blut läuft ihm aus einem Mundwinkel.>", sourceObjectiveStatus = "unverified-source-field" }
quests[29734] = { id = 29734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Tiefenschmiede", sourceObjective = "Ich spüre das Feuer des Lebens in Euch, {class}. Ich akzeptiere Eure Ehrerbietung! Nehmt dies als Zeichen meiner Dankbarkeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[29735] = { id = 29735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Steinsiegel", sourceObjective = "Ich spüre das Feuer des Lebens in Euch, {class}. Ich akzeptiere Eure Ehrerbietung! Nehmt dies als Zeichen meiner Dankbarkeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[29736] = { id = 29736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Dunkelfeder", sourceObjective = "Euer Geist steckt voller Leben, junger {class}. Ich freue mich über den Respekt, den Ihr mir zollt, und gebe Euch dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29737] = { id = 29737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Feuerbart", sourceObjective = "Ich spüre das Feuer des Lebens in Euch, {class}. Ich akzeptiere Eure Ehrerbietung! Nehmt dies als Zeichen meiner Dankbarkeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[29738] = { id = 29738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Mondlanze", sourceObjective = "Der Himmel, mit seinen unzähligen Sternen, bietet die Antworten auf alle irdenen Fragen, {name}. Mag es sein, dass wenn der Weise und Glückliche zu ihnen aufblickt, er die tiefere Wahrheit findet?", sourceObjectiveStatus = "unverified-source-field" }
quests[29739] = { id = 29739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahnin Windsang", sourceObjective = "Der Himmel, mit seinen unzähligen Sternen, bietet die Antworten auf alle irdenen Fragen, {name}. Mag es sein, dass wenn der Weise und Glückliche zu ihnen aufblickt, er die tiefere Wahrheit findet?", sourceObjectiveStatus = "unverified-source-field" }
quests[29740] = { id = 29740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahnin Immerschatten", sourceObjective = "Im endlosen Glitzern der Sterne verbergen sich die Antworten auf alle irdischen Mysterien, {name}. Darf man dann nicht annehmen, dass der Weise und der Glückspilz beim Blick nach oben die Wahrheit entdecken könnten?", sourceObjectiveStatus = "unverified-source-field" }
quests[29741] = { id = 29741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Sekhemi", sourceObjective = "Alle Tol'vir waren einst wie ich. Nun besteht mein Volk aus Fleisch und Blut und benötigt die Weisheit der Zeitalter mehr als je zuvor.", sourceObjectiveStatus = "unverified-source-field" }
quests[29742] = { id = 29742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Menkhaf", sourceObjective = "Alle Tol'vir waren einst wie ich. Nun ist mein Volk aus Fleisch und Blut und braucht die Weisheit der Zeitalter dringender als je zuvor.", sourceObjectiveStatus = "unverified-source-field" }
quests[29743] = { id = 29743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missgestalt", description = "Die Statue und die sie umgebenden Ruinen sind eindeutig uralt. Dieses Land besitzt offenbar eine tiefgründige Geschichte. Das bedeutet, dass es nicht aus dem Kataklysmus entsprungen sein kann.\n\nDoch obwohl diese Gewässer nunmehr seit Ewigkeiten erforscht wurden, gibt es kein Anzeichen für etwas anderes als offene See.\n\nWenn Ihr die Einzelteile dieser zerbrochenen Statue zeichnen würdet, könntet Ihr vielleicht ein wenig Licht auf die Ursprünge dieses Kontinents werfen.", sourceObjective = "Erstellt Zeichnungen von jedem Einzelteil der antiken Statue.", sourceObjectiveStatus = "unverified-source-field" }
quests[29744] = { id = 29744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naturschutz", description = "Waldgeister sind nicht für ihre Wanderlust bekannt, deswegen wundert es mich, dass sie sich bis zum Steinmetzviertel vorgewagt haben. Irgendetwas muss sie aus ihrem normalen Lebensraum vertreiben.\n\nDiese Geister leben eigentlich in den Wäldern der Verlorenen, gleich nördlich von hier. Ich würde ja selbst dorthin gehen, aber ich hörte, dass die Wälder verwunschen sein sollen.\n\nDas ist dann also nicht mehr drin.\n\nWir werden es wohl nie erfahren.\n\n<Weng hustet.>\n\nEs sei denn... es findet sich für diese Aufgabe <ein großer starker Abenteurer/eine große starke Abenteurerin> wie IHR! Was sagt Ihr dazu?", sourceObjective = "Untersucht die Wälder der Verlorenen, nordöstlich des Grünsteinbruchs.", sourceObjectiveStatus = "unverified-source-field" }
quests[29745] = { id = 29745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Misere der Geister", description = "<Lebende Statuen wüten in den Wäldern.\n\nBis jetzt scheinen sie sich damit zufrieden zu geben, die Waldgeister in Stücke zu hauen, aber wenn sie so weitermachen, haben die Pandaren bald andere Sorgen als nur die verschwundene Jade.>", sourceObjective = "Schaltet 10 steingebundene Zerstörer in den Wäldern der Verlorenen aus und offenbart ihre Quelle.", sourceObjectiveStatus = "unverified-source-field" }
quests[29747] = { id = 29747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Zyklus durchbrechen", description = "<Mogubeschwörer rufen die unglückseligen Geister aus der Unterwelt herauf und sperren sie in diese Statuen ein.\n\nAnscheinend reicht es nicht aus, die Statuen zu zerstören, um diesen Kreislauf zu unterbrechen.>", sourceObjective = "Tötet 8 Shan'ze-Geisterbinder auf der Terrasse der Zehn Donner.", sourceObjectiveStatus = "unverified-source-field" }
quests[29748] = { id = 29748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simulakrumwerfen", description = "<Die geborstenen Überreste einer uralten Mogustatue. Sie sieht aus, als ob sie auch vor ihrer Zerstörung nie von Leben erfüllt war.\n\nWelche dunkle Magie die Mogu auch immer hier verwenden, sie scheint die brüchigen Statuen deutlich robuster zu machen. Wir sollten sie besser zerstören, solange sie leer sind und wir die Gelegenheit dazu haben.\n\nEin guter alter Tritt sollte dazu ausreichen.>", sourceObjective = "Tretet 6 leere Zerstörer auf der Terrasse der Zehn Donner um.", sourceObjectiveStatus = "unverified-source-field" }
quests[29749] = { id = 29749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein dringendes Anliegen", description = "<Euer Verstand wird von einem Heulen erschüttert. Darunter vernehmt Ihr eine kaum wahrnehmbare Stimme, wie von weit her.>\n\nBitte... helft... inmitten der Ruinen... ein Ritual... beschwören...\n\n... sollte nicht hier sein...\n\nMein Stab... auf dem Altar... nehmt ihn. Bitte beeilt Euch.", sourceObjective = "Bergt den Stab von Pei-Zhi und unterbrecht das Beschwörungsritual der Mogu im Zentrum der Terrasse der Zehn Donner.", progress = "Geistbindung! Wie konnte es den Mogu gestattet werden, mit solch widerwärtigen Praktiken fortzufahren?! Und jetzt steh' ich hier: Das Produkt einer halb gescheiterten Beschwörung...\n\n<Der Geist zürnt noch ein wenig vor sich hin und wendet sich dann Euch zu.>\n\nIn welchem Jahrhundert befinden wir uns?", completion = "Gestatten, Pei-Zhi, meines Zeichens Meistergeistweiser unter dem letzten Pandaren-Kaiser Shaohao.\n\nZumindest... war ich das einmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29750] = { id = 29750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geistergefäße", description = "Die Geisterklauen sind eine Sekte von Moguassassinenpriestern, die zu den Hochzeiten des Mogureiches die gefürchtetste und hervorragendste Truppe des Reiches darstellten.\n\nAlle ihre Mitglieder vermochten, einen Todeshieb auszuführen, der den Geist des Feindes in eine Jadeflasche bannte, um ihn dann an einen Geisterbinder auszuliefern.\n\nWenn Ihr weiter oben in den Ruinen auf Geisterklauen stoßt, solltet Ihr Folgendes wissen: An ihren Gürteln sind die verfluchten Geistergefäße befestigt.\n\nBefreit sie von dieser Bürde und bringt die Flaschen zu mir zurück.", sourceObjective = "Sichert 8 Geisterflaschen von den Shan'ze-Geisterklauen auf der Terrasse der Zehn Donner.", progress = "Dass die Mogu über all diese Jahre weiter die Geisterklauen ausgebildet haben...\n\nHabt Ihr die Flaschen?", completion = "Ich danke Euch, {class}.\n\nIch kann bereits die Geister in diesen Flaschen spüren - ich höre ihre Schreie voller Angst, Verwirrung und... Zorn.", sourceObjectiveStatus = "unverified-source-field" }
quests[29751] = { id = 29751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritualartefakte", description = "So viele Geister werden hier in Gefangenschaft gehalten... Ich kann sie überall spüren. Selbst die Wände dienen als Käfig für die schon lange Verstorbenen.\n\n{name}, wir können den Zauber, der über diesem Ort liegt, nicht einfach brechen. Denn dann würden zahllose gepeinigte Seelen ziellos umher irren. Sie brauchen ein Signal - etwas, das sie leitet.\n\nMit Eurer Hilfe könnte ich einen Tan-Chao erstellen: eine Brücke von dieser Welt in den Himmel. Für dieses Ritual benötige ich eine Schale, eine Kerze und einen Jadecong. Ihr solltet all diese Dinge in den Ruinen finden können.", sourceObjective = "Bringt Pei-Zhi eine gesprungene Ritualschale, eine geruchsintensive Ritualkerze und einen Jadecong von der Terrasse der Zehn Donner.", progress = "Habt Ihr die Ritualgegenstände gefunden? Ohne sie können wir die Geister nicht zurückgeleiten.", completion = "Gut gemacht. Damit kann ich das Ritual abhalten und alle Geister hier, unter anderem mich selbst, dorthin zurückgeleiten, wo sie hingehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[29752] = { id = 29752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verirrten Seelen", description = "Der Vorgang der Massenbeschwörung, wie hier von den Mogu abgehalten, hat auch unerwünschte Nebeneffekte. Einige der Geister kommen zu verstört oder unruhig hier an, um sich leiten zu lassen. Dann werden sie erst einmal isoliert, bis ihre Verzweiflung sie leichter beeinflussbar macht.\n\nIch vermute, dass die Mogu irgendwo einen solchen Isolationsbereich angelegt haben, der wahrscheinlich von Geisterklauen bewacht wird.\n\nBitte nehmt noch einmal meinen Stab und verwendet ihn, um diese verlorenen Seelen einzusammeln. Ihr müsst sie nicht bekämpfen. Zeigt ihnen einfach den Stab - damit sollten sie sich einfangen lassen.", sourceObjective = "Verwendet den Stab von Pei-Zhi, um 10 verirrte Urahnen auf der Terrasse der Zehn Donner einzufangen.", completion = "Ich danke Euch, {name}. Ich werde sie mit mir in den Nether nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29753] = { id = 29753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zur Natur", description = "Ich muss Euch leider erneut um einen Gefallen bitten, {name}.\n\nDie von Euch sichergestellten Flaschen enthalten weder die Geister von Urahnen der Mogu noch jene ihrer jüngst bezwungenen Feinde, sondern vielmehr die Seelen von Tieren. Offensichtlich haben die Geisterklauen auf Wilderei zurückgegriffen, um ihre Simulakren zu erwecken.\n\nLeider macht dies unsere Aufgabe komplizierter, da ich Tiere nicht mit durch den Tan-Chao nehmen kann.\n\nBringt diese Flaschen nach Westen in das Gezeitenblickdickicht und zerschlagt sie, damit die Tiere in die Natur zurückkehren können. Einige werden ganz sicher so zornig sein, dass Ihr sie erst beruhigen müsst.", sourceObjective = "Befreit 8 Tiergeister, indem Ihr die Geisterflaschen im Gezeitenblickdickicht auf den Boden werft.", completion = "Ihre Körper sind schon vor langer Zeit in ihre Heimat zurückgekehrt - jetzt können ihre Seelen ihnen folgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29754] = { id = 29754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Verbindung zwischen Erde und Himmel", description = "Wir sind jetzt bereit, den Tan-Chao zu öffnen und die Seelen ihrem Frieden zuzuführen.\n\nEs wäre sehr freundlich, wenn Ihr mir noch einmal helfen könntet. Die Mogu werden sicher das Ritual bemerken und alles tun, um es aufzuhalten. Ich benötige nur ein paar Momente ungestörter Konzentration. Dann wird der Weg so weit geöffnet sein, dass er nicht mehr geschlossen werden kann.\n\nWenn Ihr mir noch einmal helfen möchtet, begleitet mich bitte zur Ritualstätte.", sourceObjective = "Beschützt Pei-Zhi während seines Rituals auf der Terrasse der Zehn Donner.", sourceObjectiveStatus = "unverified-source-field" }
quests[29755] = { id = 29755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ende der Pei-n", description = "<Die Geister der Urahnen strömen in den Tan-Chao, Pei-Zhis Brücke in die Freiheit.\n\nEine letzte Kammer befindet sich in den Ruinen gleich nördlich des Tan-Chao. Die Luft darüber vibriert vor schändlicher Energie. Shan Jitong hat sein Werk bereits begonnen.>", sourceObjective = "Bekämpft Shan Jitong und rettet Pei-Zhi am Sitz des Geistererweckers auf der Terrasse der Zehn Donner.", completion = "Dies muss ein Zeitalter großer Kämpfe sein, wenn es solche Helden wie Euch hervorbringt. Ich erwarte, dass große Abenteuer vor Euch liegen.\n\nEs war mir eine Ehre, Euch kennengelernt zu haben, {name}.\n\nIch werde hier bleiben, bis die letzten Geister den Tan-Chao passiert haben und dann selbst hinübergehen.\n\nAber der Todesfluch des Geistererweckers macht mir immer noch Sorgen...\n\n\"Ihr werdet den Donner nicht besiegen können.\"\n\nWas kann er damit gemeint haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[29756] = { id = 29756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bescheidenes Opferangebot", description = "Ich bin fast bereit für das Ritual - wir benötigen nur noch eine einzige Sache. Eine Opfergabe.\n\nKeine Sorge, ich meine kein Blutopfer. Nur etwas Nahrung.\n\nIm Gezeitenblickdickicht im Nordwesten wachsen ganz sicher ein paar Pilze, die sich dafür eignen. Bitte bringt mir einige davon.", sourceObjective = "Sammelt 10 Gezeitennebelkappen im Gezeitenblickdickicht ein.", progress = "Selbst Tote haben Hunger.", completion = "Ich danke Euch, {name}. Diese Pilze machen als Opfergabe vielleicht nicht viel her, aber die Erinnerung an sie wird ausreichen, die Geister anzulocken.\n\nAußerdem schmecken sie gebraten ganz köstlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[29757] = { id = 29757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trötenkröten", description = "Habt Ihr von den Problemen bei den Teichen gehört?\n\nDie Kröten dort vermehren sich wie verrückt! Das ist zu einem echten Problem für die Lotusbauern geworden.\n\nZufälligerweise stelle ich eine Marmelade aus gallertartigem Froschlaich her. Ich nenne sie \"Trötenkröten\" und sie kommt bei der Jugend hier sehr gut an. Ich kann die nicht lange auf Lager halten.\n\nWenn Ihr zu den Teichen unterwegs seid, könntet Ihr allen einen Gefallen tun, indem Ihr einige dieser Kröteneier, ähm... befreit.\n\nUnd in diese Flasche befördert. Für mich.\n\nHaltet einfach nach Blasen Ausschau und schöpft daraus!", sourceObjective = "Holt Kröteneier von 8 Blasen gurgelndem Froschlaich aus dem oberen Bereich der Teiche der Reinheit.", completion = "Wenn die Kinder mich jetzt fragen: \"Habt Ihr Trötenkröten?\" - Dann kann ich mit JA antworten!", sourceObjectiveStatus = "unverified-source-field" }
quests[29758] = { id = 29758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schöner Rücken kann entzücken", description = "<Der Panzer dieser Drachenschildkröte ist hart wie Stein und tief zerfurcht. Einer der Einheimischen kann damit bestimmt etwas anfangen.>", sourceObjective = "Bringt Kroshs Rücken zu Yan in Neu-Cifera.\n\nBereitgestellter Gegenstand:", completion = "Jetzt schaut Euch DAS an! Was für ein wunderschöner Panzer!\n\nGut, dass Ihr ihn zu mir gebracht habt. Er ist ideal für einen fantastischen Servierteller.\n\nBitte, nehmt dies als Dank für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29759] = { id = 29759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kung Din", description = "Ich hoffe, Ihr seid dieser nächsten Aufgabe gewachsen, denn unsere Leben hängen davon ab.\n\nEs gibt nur einen Schlüssel, um uns von unseren Ketten zu befreien. Und leider hängt dieser Schlüssel um den Hals des Haustigers der Ho-zen, Kung Din.\n\nSie halten den Tiger in der großen Grube im Norden. Um den Schlüssel zu erhalten, muss man den Tiger allerdings töten.", sourceObjective = "Holt Euch den Schlingschwanzschlüssel, indem Ihr Kung Din tötet.", progress = "Habt Ihr ihn gefunden?", completion = "Ja, mit diesem Schlüssel kann ich uns von unseren Ketten befreien.\n\nIhr habt uns von diesem widerwärtigen Ort erlöst.", sourceObjectiveStatus = "unverified-source-field" }
quests[29760] = { id = 29760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grubenkämpfer", description = "Um ein meisterhafter Grubenkämpfer zu werden, muss man sicherlich noch mehr machen...\n\nVielleicht weiß Korgol Schädelquetscher, der die Todesgrube des Dunkelmond-Jahrmarkts auf dem Dunkelmond-Jahrmarkt leitet, mehr.", sourceObjective = "Sprecht mit Korgol Schädelquetscher auf dem Dunkelmond-Jahrmarkt.\n\nBereitgestellter Gegenstand:", completion = "Schön, Euch zu sehen, {class}.\n\nEin Schmuckstück reicht nicht, um ein meisterhafter Grubenkämpfer zu werden.\n\nEs ist an der Zeit, dass Ihr beweist, was in Euch steckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29761] = { id = 29761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meisterhafter Grubenkämpfer" }
quests[29762] = { id = 29762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familienandenken", description = "Wir haben vor Kurzem eine harte Schlacht gegen die Ho-zen in der Mondwasserzuflucht verloren.\n\nWir haben so viele Leute rausgeholt wie nur irgend möglich, aber dennoch haben viele von uns dort ihr Leben gelassen.\n\nWir haben keine Andenken an die Toten für unsere Gebete.\n\nWenn jemand ein paar Andenken von den Toten nehmen könnte, könnten wir sie in Frieden gehen lassen und mit dem Leben fortfahren.\n\nEs würde uns wirklich viel bedeuten, wenn Ihr das tun könntet, {name}.", sourceObjective = "Sammelt 8 Perlflossenerbstücke von den toten Perlflossendorfbewohnern in der Mondwasserzuflucht ein.", progress = "Wir trauern immer noch um unsere gefallenen Brüder.", completion = "Ich danke Euch, {name}. Ihr könnt Euch gar nicht vorstellen, wie viel dies den Familien der Toten bedeutet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29763] = { id = 29763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt ihnen den Donner", description = "Die Vrykul kennen keine Angst. Sie scheinen sich sogar nach einem Tod in der Schlacht zu sehnen. Sie sind so zahlreich und werfen sich mit solcher Macht in den Kampf, dass wir nichts gegen sie ausrichten können.\n\nEs gibt jedoch einen, den sie verehren. Sein Name ist Ingvar. Wenn Ihr ihn töten könntet, würde das ihre Kampfeslust deutlich bremsen.", sourceObjective = "Verteidiger Mordun hat Euch gebeten, ihm den Kopf von Ingvar dem Brandschatzer zu bringen.", progress = "Schön zu sehen, dass es Euch gut geht, {name}.\n\nWeitere Verluste könnten wir nicht verkraften.", completion = "Hervorragend!\n\nDas könnte der Durchbruch sein, auf den wir gehofft haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29764] = { id = 29764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abrüstung", description = "Ihr könnt mir glauben, <Kamerad/Fräulein>, diese Vrykulwaffen sind verdammt unangenehm! Trügerisch gut ausbalanciert, brutal scharf - absolut tödlich.\n\nKlaut mir ein paar davon, bevor sie gegen uns eingesetzt werden.", sourceObjective = "Verteidiger Mordun möchte, dass Ihr 5 Waffen der Vrykul stehlt.", progress = "Habt Ihr ein paar Äxte der Vrykul geklaut?", completion = "<Mordun pfeift.>\n\nSeht Euch die nur mal an! Unglaublich.\n\nIch hatte eigentlich erwartet, dass diese Steinzeitmenschen mit Knüppeln herumfuchteln und Steine werfen.\n\nLeider nicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[29765] = { id = 29765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich heul' mir die Augen aus", description = "Ich hätt' die Schweine fertigmach'n können, Mann!\n\nIhnen alle eine reinschieß'n und mich dann totstell'n, wenn sie näherkomm'n! Hab'n die sonst ja auch nie kapiert.\n\nAber einer von denen hat den Trick jetzt doch kapiert... Und dann sind die alle auf mich rauf und hab'n mit meinen Augen Murmeln gespielt.\n\nHab'n meine Sachen genommen und mich hier zum Sterb'n einfach liegengelass'n, diese Wilden...\n\nDu musst mir helf'n, Mann. Lass' mich nich' so würdelos sterb'n.", sourceObjective = "Nehmt den Ho-zen-Wutschäumern Zin'Juns Sachen wieder ab.\n\nWenn Ihr Zin'Jun verliert, sprecht mit ihm am Aufstieg der Wirbelnden Winde.", progress = "Hast du meine Sachen, Mann?", completion = "<Zin'Jun schluchzt... Glaubt Ihr jedenfalls.>\n\nDie hab'n Schnuff umgebracht...\n\nWas hat Schnuff denen denn getan?", sourceObjectiveStatus = "unverified-source-field" }
quests[29766] = { id = 29766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein guter Start", description = "Unabhängig von unserer misslichen Lage sind unsere Befehle klar. Wir sind hier, um das Land zu erkunden und es für Höllschreis Flotte vorzubereiten.\n\nAber zuerst müssen wir mit diesen Wilden fertigwerden!\n\nSeht Ihr die Leichen, die ich um das Lager herum aufgestapelt habe? Ich will ganze Berge davon sehen!\n\nWir sind immer noch die Horde!\n\nDiese Maden haben noch nicht gelernt, uns zu fürchten, aber das wird sich schon bald ändern...", sourceObjective = "Tötet 4 Ho-zen-Schlickschleuderer, 4 Ho-zen-Schädelbrecher und 3 Ho-zen-Fischfänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[29767] = { id = 29767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischimbiss", description = "Das Glück belohnt die Mutigen!\n\nEure kühl kalkulierten Angriffe haben unerwartete Wirkung gezeigt. Wenn Ihr diese Fischfänger töten könnt, nachdem sie einen guten Fang gemacht haben, könnt Ihr ihnen ihre fischige Beute abnehmen.\n\nDie Feinde ausdünnen und die Verbündeten nähren - das nenne ich Effizienz!", sourceObjective = "Nehmt den Ho-zu-Fischfängern 12 ausgewachsene Karpfen ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[29768] = { id = 29768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der fehlende Schlägel", description = "{name}, ich hab's! Es ist eigentlich ganz simpel. Wir müssen einfach so viel Rabatz machen, dass er keine Chance hat, davor die Ohren zu verschließen.\n\nSieh mal einer an, dieser Gong hier steht aber genau am rechten Fleck! Wenn ich mich nicht irre, dann haben sie ihn bisher wohl auf genau diese Weise aufgeweckt. Wir brauchen nur den passenden Schlägel, damit der Gong so laut wie möglich wird.\n\nDer Dorfvorsteher hat mir erzählt, dass sich der Schlägel bei der Brauerei Ki-Han am Fluss südwestlich von hier befindet. Es ist nicht weit. Macht es Euch etwas aus, ihn für mich abzuholen, während ich hier das Dorf vorwarne?", sourceObjective = "Beschafft den Dai-Lo-Pausenhammer bei der Brauerei Ki-Han.", progress = "Nun, sie sind gewarnt, dass es gewarnter nicht mehr geht. Habt Ihr den Schlägel?", completion = "Ha, {name}! Das nenne ich einen Schlägel. Dann wollen wir mal auf die Pauke - oder eher den Gong - hauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29769] = { id = 29769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strolche!", description = "Ich suche weiter nach Möglichkeiten, diesen hartnäckigen Tiefschläfer hier aufzuwecken, aber auf dieser Insel lauert einfach an jeder Ecke ein neues Ärgernis. Die komplette Vegetation ist mit Shed-Ling verseucht, hasenartigen Dieben und Plünderern.\n\nDiese Strolche!\n\nSie vermehren sich schneller, als wir sie töten können! Aber ich habe genau die richtige Lösung für ein Problem wie dieses: Tötet sie schneller! Jetzt, da Ihr hier seid, sollte das ja kein Problem mehr sein, oder was sagt Ihr, {name}?", sourceObjective = "Tötet 10 Shed-Ling.", completion = "So wird das gemacht, {name}! Ihr taucht auf und Probleme lösen sich fast wie von selbst. Das ist nur einer der vielen Gründe, warum ich Euch mag!", sourceObjectiveStatus = "unverified-source-field" }
quests[29770] = { id = 29770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch essbar", description = "Die Shed-Ling sind mit einem Großteil der Ernte davongerannt, aber sie haben sich mehr geschnappt, als sie essen können. Sie müssen ihre Beute irgendwo lagern - zumindest den Teil davon, den sie mögen.\n\nKönntet Ihr Euch auf die Suche machen und die Feldfrüchte zurückbringen? Ich habe hier eine ganze Insel zu versorgen und jedes bisschen Gemüse hilft mir dabei.", sourceObjective = "Beschafft 3 ausgegrabene Rüben, 3 gestohlene Karotten und 3 stibitzte Kürbisse wieder.", progress = "Seit Wugou, der Geist der Erde, eingeschlafen ist, ist der Boden trockener geworden und es wird immer schwerer, neue Saat zum Sprießen zu bringen. Wir müssen so viele Lebensmittel wie möglich horten - ansonsten wird der Insel eine harte Zeit bevorstehen.", completion = "Einige hiervon sind ja angebissen! Ach, was soll's... Wir finden schon einen Verwendungszweck.\n\nVielen Dank für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[29771] = { id = 29771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Härter als Holz", description = "Besorgt mir ein paar Holzbretter von der Baustelle in der Nähe der Brauerei Ki-Han.\n\nIhr kennt die Größe meiner Stärke noch nicht, daher werde ich sie Euch demonstrieren.", sourceObjective = "Sammelt 12 weggeworfene Holzbretter.", progress = "Habt Ihr erledigt, was ich Euch aufgetragen hatte?", completion = "Gut.\n\nMein Kopf ist härter als das härteste Holz.\n\nTretet zurück und lasst mich Eure Zweifel zerstreuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29772] = { id = 29772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabatz", description = "Seid Ihr bereit, {name}? Ich glaube, dass wir uns besser etwas besorgt hätten, das wir uns in die Ohren stopfen könnten, aber dafür ist es jetzt ein bisschen zu spät. Denkt einfach immer daran, dass das fiepende Geräusch, dass Ihr für die nächsten paar Stunden hören werdet, das Fiepen des Sieges ist!\n\nDie Ehre gebührt Euch, {name}. Schlagt den Gong, sobald Ihr bereit seid!", sourceObjective = "Schlagt den Gong.", completion = "Hmm... Nun, das ist definitiv das Fiepen, dass ich befürchtet hatte, aber ich hatte mir etwas mehr Reaktion von Wugou erhofft. Dieser Kerl schläft wirklich tief, so viel ist sicher.\n\nDas ist schon in Ordnung, {name}. Ich habe noch eine andere Idee, für die wir kaum etwas vorbereiten müssen. Genau, wie ich es mag.", sourceObjectiveStatus = "unverified-source-field" }
quests[29774] = { id = 29774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht ins Gesicht!", description = "Nun gut, {name} - ich hatte mir schon Gedanken darüber gemacht, was wir wohl probieren könnten, falls die Idee mit dem Gong nicht funktionieren würde, und es ist mir einfach so eingefallen! Ein Schwall kaltes Wasser ins Gesicht macht mich immer hellwach! Und bei jemandem, der so trocken und erdig ist, muss das gleich den doppelten Effekt haben!\n\nKönntet Ihr Shu, den Geist des Wassers, vielleicht darum bitten, uns auszuhelfen? Er sollte in dem Teich neben dem Wasserfall auf der anderen Seite des Baumes spielen.", sourceObjective = "Erbittet Shus Hilfe, um Wugou aufzuwecken, den Geist der Erde.", completion = "JUHU! {name}, wir sind schon ein tolles Team. Wie ich immer zu sagen pflege: Hartnäckigkeit ist besser als Planung.", sourceObjectiveStatus = "unverified-source-field" }
quests[29775] = { id = 29775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Körper und Geist von Shen-zin Su", description = "So, damit wären wir hier fertig, oder nicht? Nun, da diese beiden hier Euch liebgewonnen haben, müssen wir sie nur noch zum Tempel der Fünf Sonnenaufgänge zurückbringen.\n\nGeht ruhig schon vor. Ich verabschiede mich hier noch und komme dann nach.", sourceObjective = "Bringt Shu und Wugou, die Geister des Wassers und der Erde, zum Tempel der Fünf Sonnenaufgänge. An der Straße steht ein Wagen, der Euch dorthin bringen wird.", completion = "Ihr habt Euch sehr gut geschlagen, mein junger Schüler. Drei der vier Geister sind in den Tempel zurückgekehrt. Wir sind den Antworten, die wir suchen, ein bedeutendes Stück näher.", sourceObjectiveStatus = "unverified-source-field" }
quests[29776] = { id = 29776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgenhauch", description = "Der vierte und letzte Geist ist Dafeng, der Geist des Windes. Wenn er sich gerade nicht durch die Himmel schwingt, hält er sich auf dem Grat der Lachenden Winde westlich von hier auf. Ich habe sowohl Aysa als auch Ji dorthin geschickt, um Euch bei der Suche zu helfen.\n\nWenn Ihr bereit seid, werde ich helfende Winde beschwören, die Euch zur Spitze des Tempels tragen werden. Von dort aus müsst Ihr die Brücken nach Westen überqueren, um Ji in Morgenhauch zu treffen.", sourceObjective = "Trefft Ji Feuerpfote in Morgenhauch.", completion = "{name}, lasst Euch umarmen! Diesmal waren wir ja nicht allzu lang getrennt - gut so!\n\nIhr habt mit Aysa zusammengearbeitet, oder? Unsere verschiedenen Überzeugungen haben uns lange Zeit voneinander ferngehalten, deshalb weiß ich nur wenig über sie. Aber jetzt, da ich sie ihre Rituale durchführen sehe, muss ich zugeben, dass sie mit ihrer Anmut und Disziplin einen seltsam verlockenden Eindruck auf mich macht.\n\nAber wir sollten unsere Gedanken dringenderen Angelegenheiten zuwenden, denkt ihr nicht? {name}, nehmen wir uns dieses Affenproblems an, während wir nach Dafeng suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29777] = { id = 29777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Werkzeuge des Feindes", description = "Die Ho-zen haben unsere Pinsel gestohlen und beschmieren unsere Schriftrollen mit ihren eigenen \"Weisheiten\"... wenn man das so nennen darf. Falls Ihr hier seid, um zu helfen, dann haltet sie auf und bringt uns unsere Pinsel zurück, bevor sie noch mehr Schaden anrichten können!", sourceObjective = "Beschafft 8 farbgetränkte Pinsel wieder.", progress = "Ich möchte die Ho-zen nicht für ihre Ambitionen verunglimpfen - jedes Volk muss seinen eigenen Weg gehen. Was diesen Vorfall betrifft, gefährden sie aber unser Leben und unsere Kultur. Das können wir nicht zulassen", completion = "Ich bin Euch zu Dank verpflichtet, junger {class}. Schon bald werde ich mit der mühseligen Arbeit beginnen, unsere Weisheiten erneut niederzuschreiben, damit die Schriftrollen wieder aufgehängt werden können, um nachfolgende Generationen zu leiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29778] = { id = 29778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umgeschriebene Weisheiten", description = "{name}, wir müssen dem Ältesten Shaopai helfen. Es gibt nur wenige, die unsere Güte mehr verdient hätten als er.\n\nAuf dem Weg hierher sind Euch bestimmt die Schriftrollen aufgefallen, die in der Grotte im Süden hängen. Die Ho-zen haben viele davon besudelt und leider kann der Schaden nicht rückgängig gemacht werden. Wir werden uns des Problems auf direkte Art annehmen - indem wir die Schriftrollen zusammen mit den Schmierereien der Ho-zen vernichten.\n\nSorgt Euch nicht um Shaopai. Die Leute werden zusammenkommen und ihm dabei helfen, die Weisheiten erneut niederzuschreiben. Dafür werde ich sorgen.", sourceObjective = "Verbrennt 5 verschandelte Rollen der Weisheit.", completion = "Ihr seid herzensgut, {name}. Ihr beweist das stets aufs Neue und ich bin froh, an Eurer Seite stehen zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29779] = { id = 29779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der direkte Weg", description = "Jetzt reicht's, {name}. Das ist das zweite Mal, dass wir uns mit plündernden Ho-zen herumschlagen mussten. Es ist an der Zeit, dass wir uns um das Problem kümmern - auf die Huojin-Art. Kein Abwarten mehr. Keine Meditation. Wir werden das Übel bei der Wurzel packen.\n\nWir gehen direkt ins Ho-zen-Dorf im Norden und bestrafen diese stinkenden Unruhestifter. Ich hatte mich schon darauf gefreut, endlich wieder an Eurer Seite kämpfen zu dürfen, {name}.", sourceObjective = "Tötet 20 Ho-zen in Fe-Feng.", sourceObjectiveStatus = "unverified-source-field" }
quests[29780] = { id = 29780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Unrecht tun", description = "{name}, Ihr müsst verstehen, dass der Weg der Huojin keineswegs der Weg der Gewalt ist. Wenn wir kämpfen müssen, zögern wir keinen Moment, aber wenn wir nicht kämpfen müssen, werden wir auch keinen Kampf anzetteln. Allerdings ist es oft der direkteste Weg, der Schlange den Kopf abzuschlagen, wie es so schön heißt.\n\nDie Ho-zen haben einen Anführer, der all diese Angriffe auf unsere Siedlungen anzettelt. Wenn wir Ruk-Ruk aus dem Spiel nehmen, müssen wir nicht alle Ho-zen ausrotten, um die Angriffe zu stoppen.\n\nIch weiß, dass Ihr kein Anhänger der Huojin seid, {name}, aber Ihr werdet mir sicher dabei helfen, das zu tun, was getan werden muss, oder?", sourceObjective = "Tötet Ruk-Ruk, den Häuptling von Fe-Feng.", sourceObjectiveStatus = "unverified-source-field" }
quests[29781] = { id = 29781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Affen unzugänglich aufbewahren", description = "Die Affen haben sich bei ihren Angriffen auf das Dorf etliches unter den Nagel gerissen. Wir sollten den Verlust einiger Proviantpakete verkraften können, aber bei dem Gedanken an Affen mit Feuerwerkskörpern wird mir ein wenig flau im Magen. Außerdem weiß man ja nie, wann wir selbst einmal ein paar Raketen benötigen, nicht wahr?\n\nHelft mir, die gestohlenen Feuerwerkskörper aus ihrem Dorf zurückzuholen, {name}!", sourceObjective = "Beschafft 8 gestohlene Feuerwerksbündel wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[29782] = { id = 29782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Härter als Knochen", description = "Diese große Säule des Jadetigers scheint unter all diesen Ho-zen-Gebäuden fehl am Platz zu sein.\n\nSie macht aber auch einen sehr harten Eindruck. Wirklich sehr hart.\n\nIhr wisst genau, wer sich dafür interessieren dürfte.", sourceObjective = "Bringt die Säule des Jadetigers zu Jojo Eisenstirn in Morgenhauch.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[29783] = { id = 29783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Härter als Stein", description = "Sammelt ein paar Steinblöcke beim Grat der Lachenden Winde im Süden für mich.\n\nIhr konntet Euch nun schon zweimal von meiner Stärke überzeugen, doch Euer Blick verrät mir, dass Ihr immer noch zweifelt... aber nicht mehr lange.", sourceObjective = "Sammelt 12 herrenlose Steinblöcke.", progress = "Die Stärke des Körpers kann ohne die Stärke des Geistes nicht existieren.", completion = "Gut.\n\nMein Kopf ist härter als der härteste Stein.\n\nTretet zurück und lasst mich Eure Zweifel zerstreuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29784] = { id = 29784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Gleichgewicht", description = "Aysa hat auf dem See meditiert, seit wir hier angekommen sind. All ihre Gedanken sind auf Dafeng gerichtet. Ich weiß nicht, was sie sich dort draußen zu finden erhofft, aber sie ist kein Dummkopf und Meister Shang Xi persönlich hat sie mit dieser Aufgabe betraut.\n\nIhr werdet über die Seile, die am Ende des Docks festgemacht sind, zu ihr gelangen müssen. Das wird Eure Balance auf die Probe stellen, aber ich denke, dass Ihr der Herausforderung gewachsen seid.", sourceObjective = "Balanciert über die Seile und sprecht mit Aysa Wolkensänger auf dem Morgenhauchsee.", sourceObjectiveStatus = "unverified-source-field" }
quests[29785] = { id = 29785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dafeng, der Geist des Windes", description = "Wenn Ihr nur lang genug zuhört, wird der Wind Euch die Antwort zutragen.\n\nDafeng, der Geist der Luft, hat den Himmel aus Furcht vor der Onyxschlange Zhao-Ren verlassen. Er versteckt sich in der Kammer des Raunens an der Südseite des Plateaus.\n\nGeht zu ihm. Ji und ich werden dort zu Euch stoßen.", sourceObjective = "Sprecht mit Dafeng, dem Geist der Luft, in der Kammer des Raunens.", sourceObjectiveStatus = "unverified-source-field" }
quests[29786] = { id = 29786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht um den Himmel", description = "Dafeng, der Geist der Luft, hat furchtbare Angst vor der Onyxschlange Zhao-Ren, {class}. Wir müssen ihm helfen, sich seiner Angst zu stellen, oder ihr an seiner statt gegenübertreten.\n\nAls ich Ji von der Schlange erzählt habe, sagte er, er habe eine Idee. Er wollte außerhalb der Kammer mit den Vorbereitungen beginnen. Ich muss zugeben, dass ich ihn trotz seiner unbesonnenen Art um seine Leidenschaft und Überzeugung beneide.\n\nLasst uns nach draußen gehen, um uns der Onyxschlange zu stellen.", sourceObjective = "Besiegt die Onyxschlange Zhao-Ren mithilfe von Jis Feuerwerk.", sourceObjectiveStatus = "unverified-source-field" }
quests[29787] = { id = 29787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweis der Würdigkeit", description = "Die vier Elementargeister werden Euch dabei helfen, mit dem Land zu sprechen und herauszufinden, woran es leidet, aber vorher habe ich noch eine kleine Aufgabe für Euch.", sourceObjective = "Besiegt den Wächter der Ältesten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29788] = { id = 29788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unschöne Natur", description = "Ihr hattet es schon einmal mit Waldgeistern im Tal des Anbrechenden Morgens zu tun, aber die Waldgeister in diesem Gehölz sind von einer komplett anderen Sorte. Gemeiner und gefährlicher.\n\nFalls Ihr ein paar dieser Wichte beseitigen könntet, wären die Elementargeister Euch dankbar.", sourceObjective = "Tötet 8 Dornzweigstrolche.", sourceObjectiveStatus = "unverified-source-field" }
quests[29789] = { id = 29789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klein, aber wichtig", description = "Ich bin müde, {name}. Ich muss mich ausruhen.\n\nWir müssen ein Ritual durchführen, aber wir benötigen einige der Talismane aus diesem Gehölz. Wenn Ihr es durchsucht, solltet Ihr sie überall von den Bäumen hängen sehen.\n\nIch nehme an, dass es einem jungen Hüpfer wie Euch nichts ausmacht, wenn ich mich hier hinsetze und ein wenig ausruhe, während Ihr die Talismane sammelt?", sourceObjective = "Sammelt 8 Kun-Pai-Ritualtalismane.", sourceObjectiveStatus = "unverified-source-field" }
quests[29790] = { id = 29790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weisheit überliefern", description = "Ihr werdet Eure Reise schon bald ohne mich fortsetzen müssen. Bleibt ein Weilchen und lauscht den Worten eines alten Mannes. Mein Wissen soll als Fundament des Euren dienen, sodass Ihr zu einem größeren Helden werden könnt, als ich es jemals war.", sourceObjective = "Hört Meister Shang Xi zu.", sourceObjectiveStatus = "unverified-source-field" }
quests[29791] = { id = 29791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Leiden von Shen-zin Su", description = "Die Zeit der Trauer wird noch kommen. Aber der Ballon steht bereit und Shen-zin Su erwartet uns.\n\nWir werden die ersten Pandaren sein, die nach Hunderten von Jahren wieder mit Shen-zin Su sprechen dürfen. Es ist eine große Ehre.", sourceObjective = "Steigt in den Heißluftballon ein und sprecht mit Shen-zin Su.", sourceObjectiveStatus = "unverified-source-field" }
quests[29792] = { id = 29792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Großem berufen", description = "Es liegt nun an Euch allen, den Stachel aus dem Fleisch Shen-zin Sus zu entfernen. Lasst Eure Unterschiede nicht zu einem Hindernis werden. Habt Vertrauen ineinander.\n\nIm Pei-Wu-Wald lebt ein Einsiedler. Begebt Euch geradewegs zu seiner Hütte. Er weiß genau, was für dunkle Gestalten sich dieser Tage in den Bäumen verstecken.", sourceObjective = "Öffnet das Tor zum Pei-Wu-Wald.", sourceObjectiveStatus = "unverified-source-field" }
quests[29793] = { id = 29793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Böse aus dem Meer", description = "Ich weiß nicht genau, was dieses Böse ist, das den Wald befallen hat, {name}, aber ich weiß genau, was man dagegen tun kann. Ich denke, Ihr wisst, was ich meine...", sourceObjective = "Tötet 8 verfinsterte Gräuel oder verfinsterte Schrecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[29794] = { id = 29794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keiner wird zurückgelassen", description = "Eure Freundin hat keine Mühen gescheut, um meine Besatzung zu retten. Ich bin ihr zu tiefstem Dank verpflichtet.\n\nWir haben hier aber immer noch mit zu vielen Problemen gleichzeitig zu kämpfen: Die Feuer am Wrack müssen gelöscht, die Leute herausgeschafft und die Gefangenen an der Flucht gehindert werden. Wir schaffen das einfach nicht allein.\n\nDa sind immer noch Besatzungsmitglieder auf dem Schiff, die wir herausholen müssen, bevor das Wrack über ihnen zusammenbricht. Ich weiß, dass ich viel von Euch verlange, aber könntet Ihr uns helfen?", sourceObjective = "Rettet 3 verletzte Matrosen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29795] = { id = 29795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohre raffen", description = "Meine Männer sind unterernährt, verwundet und erschöpft, aber sie sind von der Horde. Ein jeder von ihnen wird bis zum letzten Atemzug kämpfen. Ihr seid unser neuer Verbündeter und wir werden Euch zur Seite stehen, wenn die Zeit reif ist, aber wir wären eine weitaus größere Hilfe, wenn wir bewaffnet wären.\n\nIch habe meine Männer beauftragt, Bambusrohre aus der Umgebung zusammenzusammeln, die wir zu Speeren umfunktionieren könnten. Falls es Euch nichts ausmacht, könnten wir dabei ein weiteres Paar kräftige Hände gut gebrauchen.", sourceObjective = "Sammelt 10 abgebrochene Bambusrohre.", sourceObjectiveStatus = "unverified-source-field" }
quests[29796] = { id = 29796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dringende Neuigkeiten", description = "Ich bin mir sicher, dass Aysa dieser Plan nicht gefallen wird, aber es ist der einzige Plan, den wir haben. Würde es Euch etwas ausmachen, an meiner Stelle der Überbringer schlechter Nachrichten zu sein, {name}? Sie muss wissen, was wir vorhaben, damit sie alle in Sicherheit bringen kann.", sourceObjective = "Sprecht mit Delora Löwenherz beim Wrack der Himmelssucher.", sourceObjectiveStatus = "unverified-source-field" }
quests[29797] = { id = 29797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medizinische Versorgungsgüter", description = "Wir brauchen Medikamente und Verbandszeug, um uns um unsere Verwundeten zu kümmern, aber ich habe keine Ahnung, was mit den Kisten, in denen all das verstaut war, beim Absturz passiert ist. Wenn Ihr einfach ein paar Kisten wiederfinden könntet, dann wäre ich Euch sehr dankbar.", sourceObjective = "Beschafft 8 Kisten mit medizinischen Versorgungsgütern wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[29798] = { id = 29798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein uraltes Übel", description = "{name}, ich habe nach Euch gesucht!\n\nEiner der entkommenen Seeleute hat Aysa im Schiffswrack gesehen, wie sie einem gigantischen Ungeheuer gegenüberstand. Sie braucht wahrscheinlich Eure Hilfe... Eilt zu ihr, schnell!", sourceObjective = "Bezwingt Vordraka, den Alptraum aus der Tiefe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29799] = { id = 29799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heilung von Shen-zin Su", description = "Das ist viel schlimmer, als ich erwartet hatte, aber wir können es schaffen. Wir müssen alle Heiler zusammentrommeln, um die Wunde zu schließen. Wir müssen Shen-zin Su retten.\n\nFindet so viele Heiler, wie Ihr nur könnt! Befreit sie, entbindet sie von anderen Aufgaben - tut, was immer Ihr tun müsst, damit sie hierherkommen und diese Wunde heilen.\n\nUnd passt auf, dass ihnen dabei nichts zustößt...", sourceObjective = "Rettet und beschützt die Heiler, bis Shen-zin Sus Wunde geheilt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29800] = { id = 29800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Verbündete", description = "Ich habe getan, was getan werden musste, {name}. Und es hat funktioniert. Es hätte alles viel schlimmer enden können, hätten wir nicht gehandelt. Ich wünschte nur, dass Aysa das verstehen würde.\n\nEs wird noch genug Zeit zur Besinnung geben, aber wir müssen zuerst zum Tempel der Fünf Sonnenaufgänge zurückkehren. Wir müssen sie wissen lassen, dass Shen-zin Su gerettet wurde - und wir müssen über das Schicksal dieser neuen Verbündeten entscheiden.", sourceObjective = "Kehrt zum Tempel der Fünf Sonnenaufgänge zurück. Beim Wrack der Himmelssucher wartet ein Wagen auf Euch der Euch zum Tempel bringen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[29801] = { id = 29801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewährungsprobe", description = "Hallo, {name}! Im Schwarm hat sich herumgesprochen, dass Ihr ziemlich... wie soll ich sagen... geschickte Finger habt.\n\nWir könnten jemand mit Euren Fähigkeiten für eine äußerst delikate Aufgabe gebrauchen. Bevor ich fortfahre, muss ich wissen, ob Ihr <der richtige Mann/die richtige Frau> für diese Angelegenheit seid. Wenn Euch der Krieg zum Auge der Ewigkeit führt, möchte ich, dass Ihr Hagara die Sturmbinderin bestehlt und Ihr den Entschlüsselungsring eines Kryptomanten abnehmt. Wollt Ihr Euch dieser Aufgabe stellen?", sourceObjective = "Bestehlt Hagara die Sturmbinderin im Auge der Ewigkeit in der Drachenseeleninstanz und beschafft Euch so einen Entschlüsselungsring des Kryptomanten.", progress = "Habt Ihr unsere Aufgabe abgeschlossen? Diese Artefakte sind so konstruiert, dass sie sich auflösen, wenn ihr Träger getötet wird. Nur ein geübter Dieb kann sie beschaffen.", completion = "Ihr habt einen gefunden! Ihr seid eine Zierde für Euer Volk, {name}.\n\nMit diesen Ringen kann man sogar die kompliziertesten Chiffren entschlüsseln. Leider muss der Ring dazu erst aufgeladen werden...", sourceObjectiveStatus = "unverified-source-field" }
quests[29802] = { id = 29802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verborgene Botschaft", description = "Corastrasza, die sich momentan im Zinnoberrefugium im Schattenhochland aufhält, hat eine kodierte Botschaft von großer Wichtigkeit abgefangen. Sie wird Euch alles erklären, aber zuallererst brauchen wir Eure Hilfe bei der Entschlüsselung der Nachricht.\n\nBringt Euren Entschlüsselungsring zu einem astralen Thaumaturgen in Eurer Hauptstadt - er sollte wissen, wie man ihn auflädt. Lasst Euch die verschlüsselte Nachricht von Corastrasza geben und dekodiert sie mit Eurem Entschlüsselungsring. Beeilt Euch! Die Zeit läuft uns davon...", sourceObjective = "Ladet Euren Entschlüsselungsring des Kryptomanten auf und entschlüsselt damit Corastraszasangesengte Geheimnachricht.", progress = "Ich hatte gehofft, dass Lord Devrestrasz einen kompetenten Helfer finden würde.\n\nWas habt Ihr für uns, {name}? Könnt Ihr die Botschaft entschlüsseln?", completion = "Worum geht's, um das \"Rabenholdtanwesen\"? Ich dachte, da oben im Vorgebirge des Hügellandes gäbe es nur eine zusammengewürfelte Diebesbande.\n\nWas wollen die denn mit einem Drachenei? Und noch wichtiger: Wie haben sie davon erfahren?\n\nWir brauchen Antworten, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[29803] = { id = 29803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ohren des Lichkönigs", description = "Im Fjord dient Prinz Keleseth als Arthas' Augen und Ohren.\n\nDas gefällt mir kein bisschen!\n\nMacht Arthas hier taub und blind. Damit erweist Ihr der Welt einen Gefallen.", sourceObjective = "Verteidiger Mordun in Burg Utgarde möchte, dass Ihr Prinz Keleseth tötet.", completion = "Ich wette, das hat dieses Blassgesicht gespürt!\n\nEin weiterer Schritt auf dem Weg zur Abrechnung, Arthas!", sourceObjectiveStatus = "unverified-source-field" }
quests[29804] = { id = 29804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für Schnuff!", description = "Ich wollt' eigentlich liegenbleib'n und abkratz'n, Mann.\n\nAber das geht jetzt nich'!\n\nSchnuff und ich war'n schon seit Ewigkeiten Kumpels. Was hatt'n wir für schöne Zeiten zusammen...\n\nAber ich muss erst Schnuff räch'n, Mann! Sonst kann ich ihm im Jenseits nich' unter die Augen tret'n!\n\nDer Anführer dieser Mistkerle heißt Konk. Er muss dran glaub'n - für Schnuff!", sourceObjective = "Tötet Konk.", completion = "Zin'Jun ist gestorben?\n\nWas für ein trauriger Tag, Bruder. Dafür muss dieses Gezücht bezahlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29806] = { id = 29806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wanderer", sourceObjective = "Bezwingt den herumstreifenden Raufbold in einem Kampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[29807] = { id = 29807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod dem Verräterkönig", description = "Anub'arak der Verräterkönig ist im einst stolzen unterirdischen Azjol-Nerub zuhause.\n\nEr hat unsere Heimat in den erbärmlichen Haufen Dreck verwandelt, den wir heute sehen. Er herrscht über eine Armee untoter Neruber, die dem Lichkönig die Treue geschworen haben.\n\nSetzt der Herrschaft des Verräterkönigs ein Ende.", sourceObjective = "Pionier A'zak in Azjol-Nerub hat Euch aufgetragen, Anub'arak zu besiegen. Kehrt danach mit Anub'araks zerbrochenem Panzer zu A'zak zurück.", progress = "Ist es getan, {class}? Hat der Verräterkönig endlich sein Leben ausgehaucht?", completion = "<A'zaks Augen beginnen durchdringend zu leuchten, als er den Panzer anstarrt.>\n\nEs ist VOLLBRACHT!\n\n{race}! Euer Name wird in die Annalen meines Volkes aufgenommen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29808] = { id = 29808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergesst die Eier nicht!", description = "In ganz Azjol-Nerub liegen Eier, die von den Nerubern der Geißel gehegt und gepflegt werden. Die Jungen werden bald schlüpfen um geschlachtet und als Untote wiedererweckt zu werden.\n\nDiese Eier wurden mit fauler Magie verunreinigt. Wir müssen sie unbedingt vernichten.", sourceObjective = "Pionier A'zak in Azjol-Nerub möchte, dass Ihr 6 Eier der Geißelneruber zerstört.", completion = "Keine Sorge, {race}.\n\nWir haben die meisten unserer Eier gut in Azjol-Nerub versteckt. Sie haben nur ein paar gefunden.\n\nUnser mächtiges Königreich wird wieder auferstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29809] = { id = 29809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Effiziente Ausgrabungen", description = "Dieses Handbuch beschreibt absonderliche Theorien, wie man große Arbeitergruppen wirksam einteilt, wenn sie mit gewaltigen Ausgrabungsprojekten beschäftigt sind.\n\nNachdem Ihr den Inhalt überflogen habt, wird Euch klar, dass der Verfasser des Buchs die Person sein muss, die für die übermäßig aggressiven Plünderer hier verantwortlich ist.\n\nEine Karte auf der Rückseite des Umschlags zeigt, dass der Verfasser einen Bunker in der südwestlichen Region von Uldum besitzt.\n\nVielleicht wäre es angebracht, sich einmal vorzustellen.", sourceObjective = "Bringt 'Effiziente Ausgrabungen' zu Bellok Leuchtklinge in Schnottz' Landeplatz.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[29811] = { id = 29811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Talisman des Torwächters", description = "Krik'thir, Wächter der Tore von Azjol-Nerub, war kein Verräter.\n\nEr fiel im Krieg der Spinne, als er unsere Heimat gegen die Geißel verteidigte.\n\nWie es seiner Stellung gebührte, besaß er den Schlüssel zum verborgenen Reich. Ich möchte, dass Ihr ihn bergt, damit er seinem Volk überbracht werden kann.", sourceObjective = "Pionier A'zak in Azjol-Nerub möchte, dass Ihr den Talisman des Torwächters von Krik'thir dem Torwächter erbeutet.", progress = "Wurde Krik'thirs Geist vom Fluch des Untodes befreit? Was ist mit dem Talisman?", completion = "Ich hatte es geahnt.\n\nEin Großteil des Reiches ist seit Krik'thirs letztem Kampf verschlossen geblieben. Vielleicht hat mein Volk die Tiefen bereits gesichert und wartet nur auf seine Befreiung. Vielleicht sind es jedoch auch die Gesichtslosen, die hinter verschlossenen Türen lauern.\n\nWir werden es irgendwann erfahren. Zuerst muss jedoch der freigelegte obere Teil von Azjol-Nerub von Arthas' Schmutz gesäubert werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29815] = { id = 29815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forensische Wissenschaft", description = "Diese Kreaturen sind überall - und aggressiv sind sie noch dazu! Wir müssen uns um sie kümmern, bevor noch mehr Allianzmitglieder hier auftauchen.\n\nDieses Exemplar hier ist ziemlich übel zugerichtet, aber ich konnte dennoch einige Erkenntnisse über seine Anatomie gewinnen.\n\nMit den richtigen Reagenzien sollte es mir gelingen, ein Gift zusammenzubrauen, das im Kampf gegen diese Spezies seine Wirkung nicht verfehlen wird. Es sollte sogar reichen, einfach das Gift, das ich bei mir trage, etwas zu modifizieren.\n\nZieht los und sucht mir in der Nähe des Wassers etwas Zähflüssiges Chlorophyll. Jedes halbintelligente Pflanzenwesen dürfte den Zweck erfüllen.", sourceObjective = "Sammelt 8 Einheiten zähflüssiges Chlorophyll.", progress = "Ich hoffe, Ihr hattet Erfolg. Unser Überleben hier hängt vielleicht davon ab.", completion = "Oh, ja, {name}. Damit kann ich etwas anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29820] = { id = 29820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinein in den Nexus", description = "Ich habe Kriegsmagierin Kaitlyn in den Nexus geschickt, damit sie Malygos' chaotisches Reich untersucht, aber sie hat sich seit Tagen nicht gemeldet.\n\nKönntet Ihr dorthin gehen und sie unterstützen? Sie könnte sicherlich Hilfe gebrauchen, wenn die Drachen sie nicht schon gefressen haben.", sourceObjective = "Erzmagier Berinand hat Euch gebeten, mit Kriegsmagierin Kaitlyn im Nexus zu sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29821] = { id = 29821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Miese kleine Diebe", description = "Hört mal, <Kumpel/Schätzchen>.\n\nIch hab ein paar Versorgungsdrohnen vom Luftschiff aus losgeschickt, aber die sind alle abgestürzt oder verloren gegangen. Na ja, fast alle.\n\nEine von ihnen ist hier durchs Lager gesurrt und dann bei den Wasserfällen abgeschmiert.\n\nWarum schaut Ihr nicht mal, ob Ihr die Inhalte dieser Kiste retten und hierherbringen könnt, hmm?\n\nWir haben zwar keine Drohnen mehr, aber meine Raketenstiefel könnten hier ganz nützlich sein. Die gehen ab wie eine... äh... Rakete!\n\nHa ha, ich lach mich schief...", sourceObjective = "Findet die fehlende Vorratskiste bei der Kaskade der Ruhe.\n\nBereitgestellter Gegenstand:", completion = "Diese Kiste sollte voller Vorräte sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[29822] = { id = 29822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eigenheiten des Landes", description = "Diese verfluchten Fellknäuel! Für jeden von ihnen, den wir töten, stehen plötzlich zwei neue da...\n\nNichts hat sich geändert, {name}. Befehle sind Befehle, egal, wie wenige wir sind und wie schlecht unsere Chancen stehen.\n\nIch muss Pläne schmieden und Probleme lösen.\n\nZieht in das Land und lernt seine Eigenheiten kennen. Kommt erst wieder, wenn Ihr etwas Nützliches zu berichten habt.\n\nUnd wenn Ihr unterwegs seid, seht zu, dass dieser jammernde Idiot die Klappe hält! Weggetreten!", sourceObjective = "Besucht den Schrein der Sonne, den Schrein des Mondes und tötet Djuuk Uukem.", completion = "Willkommen, Reisender.\n\nBitte, macht es Euch bequem.", sourceObjectiveStatus = "unverified-source-field" }
quests[29823] = { id = 29823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späherbericht: Der Freund meines Feindes", description = "Wisst Ihr, wir haben nicht nur nach der Allianz gesucht. Wir haben auch nach diesen watzrommeligen, flipmippischen Jinyu gesucht!\n\nNa ja, wir ha'm sie ja auch gefunden...", sourceObjective = "Hört Euch Rikos Bericht an.", completion = "Ja, ich bin weggelaufen. Na und? Ohne mich wäre Kiryn jetzt tot. Oh, Moment… sie ist bereits tot… bereits...\n\nGeht weg! Riko hat Kopfschmerzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29824] = { id = 29824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späherbericht: Butter bei die Jinyu", description = "Nachdem unser Anführer in Jade verwandelt wurde, unser Ho-zen-Führer verschwunden war und wir einen Kriegsgefangenen im Schlepptau hatten, blieb nur eins für Kiryn und mich zu tun:\n\nIns Feindesland einmarschieren und Rache nehmen.\n\nWollt Ihr wissen, wie das gelaufen ist?", sourceObjective = "Hört Euch Shokias Bericht an.", completion = "Das Wichtigste, das wir lernten, war... dass die Allianz nicht nur Freundschaft mit den Jinyu geschlossen hat, sondern sie auch mit Waffen versorgt und ihnen beibringt, wie man sie benutzt.\n\nDie Allianz hat jetzt eine Armee, die uns dreißig-zu-eins zahlenmäßig überlegen ist. Und wir - die HORDE - haben Freundschaft mit Affen geschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29825] = { id = 29825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht länger ein Schüler", description = "Einst nannte ich Urahne Nadox meinen Lehrer.\n\nDas änderte sich für immer, als ich zusehen musste, wie er, ein Diener der Verdammten, meine Freunde und meine Familie umbrachte.\n\nFindet ihn in den Tiefen und sorgt dafür, dass er für seine Verbrechen bezahlt.", sourceObjective = "Seher Ixit in Ahn'kahet hat Euch gebeten, Urahne Nadox zu töten.", progress = "Ist der mächtige Nadox endlich tot?", completion = "Ich hoffe, dass ich nun an Nadox' Stelle treten und mein Volk anführen kann.\n\nDas Reich von Azjol-Nerub wird Großes vollbringen, {race}...", sourceObjectiveStatus = "unverified-source-field" }
quests[29826] = { id = 29826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung von Ahn'kahet", description = "Prinz Taldaram und seine Geißelarmee benutzen die gleichen Barrieren, hinter denen wir einst unser Reich verbargen, um sich vor den Einheimischen der eisigen Tiefen zu schützen.\n\nDeaktiviert die Barrieren und tötet die Geißelsoldaten, die sie bewachen. Meine Streitkräfte werden zusammen mit den Einheimischen den Rest erledigen.", sourceObjective = "Seher Ixit in Ahn'kahet möchte, dass Ihr 3 Augen von Taldaram, einen Knochenschinder und Prinz Taldaram tötet.", completion = "Hervorragend.\n\n<Ihr hört einige klickende Geräusche.>\n\nUnd nun zu unserem anderen Feind...", sourceObjectiveStatus = "unverified-source-field" }
quests[29827] = { id = 29827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saurer Regen", description = "Während Ihr fort wart, haben sich immer mehr von diesen Kreaturen in der Nähe unseres Lagers versammelt. Sie scheinen eine Großoffensive vorzubereiten!\n\nWir werden drastische Mittel ergreifen müssen, wenn wir nicht sang- und klanglos untergehen wollen.\n\nHier, nehmt meine vergifteten Wurfsterne und überlegt Euch, wie Ihr ihre Reihen etwas dezimieren könnt.", sourceObjective = "Benutzt den Geborgenen Gyrokopter, um 25 Ho-zen-Magenfetzer und 25 Ho-zen-Spenkspieker zu töten.", completion = "Ausgezeichnet! Welch kreative Lösung!\n\nDas sollte sie eine Weile fernhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29828] = { id = 29828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Alptraum der Geißel", description = "Ein flüchtender Drakkaritroll hat mir von einem großen Raptorkönig namens Dred erzählt, der gegen die Seuche immun ist.\n\nFindet diesen König Dred und bringt mir einen seiner Zähne. Vielleicht kann ich daraus eine Waffe herstellen.", sourceObjective = "Kurzel in der Feste Drak'Tharon möchte, dass Ihr König Dred tötet und ihr seinen Zahn bringt.", progress = "Gibt es diese gewaltige Bestie wirklich?", completion = "<Kurzels Augen weiten sich.>\n\nBoah! Der ist ja riesig!", sourceObjectiveStatus = "unverified-source-field" }
quests[29829] = { id = 29829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diskretion ist der Schlüssel", description = "Hört mir zu, {race}.\n\nMir wurde soeben mitgeteilt, dass sich in der Violetten Festung ein Zwischenfall ereignet hat. Es scheint, als würde der blaue Drachenschwarm eine groß angelegte Invasion Dalarans vorbereiten!\n\nIch möchte, dass Ihr Euch umgehend zum Gefängnis begebt und mit Leutnant Sinclari sprecht. Sie wird Euch alles erklären.\n\nDoch das ist nicht alles. Ihr müsst äußerst diskret vorgehen. Wir dürfen die Bürger Dalarans nicht verunsichern, wenn es sich vermeiden lässt. Habe ich mich klar ausgedrückt?\n\nGut. Dann geht jetzt.", sourceObjective = "Rhonin möchte, dass Ihr zur Violetten Festung in Dalaran geht und mit Leutnant Sinclari sprecht.", completion = "Keinen Augenblick zu früh.\n\nSeid Ihr bereit, Dalaran zu verteidigen, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[29830] = { id = 29830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindämmung", description = "Meine Streitkräfte liegen am Boden, aber Malygos' Angreifer stürmen immer weiter auf uns ein.\n\nIhr müsst sie aufhalten, bis ihre Anführerin Cyanigosa auftaucht. Nur ihr Tod wird die Invasion beenden und Dalaran retten.\n\nSprecht mich an, wenn Ihr bereit seid.", sourceObjective = "Leutnant Sinclari in der Violetten Festung möchte, dass Ihr die Invasion der blauen Drachen aufhaltet. Sprecht mit ihr, wenn Cyanigosa geschlagen ist.", progress = "Ist es vorbei? Konntet Ihr dem Angriff standhalten?", completion = "Danke, mein Held!\n\nDank Eures Mutes konnte Dalaran einen weiteren Tag überstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29833] = { id = 29833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offene Rechnungen", description = "Der Prophet von Akali mag diese Welt zwar nicht mehr belästigen, doch es gibt noch immer Arbeit zu tun.\n\nAkalis Blut - ein Großteil davon - hat jemand anderem Macht verliehen und es ist dieser jemand, von dem die eigentliche Gefahr ausgeht.\n\nSchnell, {name}, macht Euch auf den Weg nach Gundrak und sprecht mit Tol'mar. Er wird Euch diesbezüglich weitere Anweisungen geben können.", sourceObjective = "Har'koa möchte, dass Ihr mit Tol'mar in Gundrak sprecht.", completion = "Hör zu, Mann. Die Arbeit, die hier erledigt werden muss, is' gefährlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[29834] = { id = 29834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gal'darah muss bezahlen", description = "War das schlimmste, was ich je gesehen hab', Mann. Der große Akali - vor meinen Augen getötet. Furchtbar...\n\nIch bin nur hier, um zu beobachten, aber so was geht nich'! Gal'darah un' seine Anhänger müssen dafür bezahlen!\n\nRäche Akalis Tod, Mann. Muss sein.", sourceObjective = "Tol'mar möchte, dass Ihr Slad'ran, Moorabi und Gal'darah in Gundrak tötet.", progress = "Hast du Akalis Tod gerächt, {race}?", completion = "Du hast es getan?! Sie sind hin?\n\nHier, Mann. Das Geschenk is' für dich, weil du den Eisigen Weiten Gerechtigkeit gebracht has'.", sourceObjectiveStatus = "unverified-source-field" }
quests[29835] = { id = 29835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gal'darah muss bezahlen", description = "Der mächtige Akali is' tot, {race}.\n\nMeine Rolle im Leben ist es, Dinge aufzuzeichnen, nich' zu kämpfen. Aber das geht nicht! Gal'darah und seine Anhänger müssen bezahlen!\n\nRäche Akalis Tod, Mann. Muss sein.", sourceObjective = "Chronistin Bah'Kini möchte, dass Ihr Slad'ran, Moorabi und Gal'darah in Gundrak tötet.", completion = "Du hast es getan?\n\nDamit hast du meine Erwartungen voll übertroffen, Mann. Das Geschenk is' für dich, weil du den Eisigen Weiten Gerechtigkeit gebracht has'.", sourceObjectiveStatus = "unverified-source-field" }
quests[29836] = { id = 29836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur ma' nachsehen", description = "Unten aus Gundrak waren fürchterliche Geräusche zu hören. In letzter Zeit sind sie lauter geworden und auch häufiger zu hören.\n\nMeine langjährige Schülerin konnte von ihrem Posten westlich von Gundrak aus die Ereignisse erfassen. Hättet Ihr vielleicht Zeit, bei Ihr nachzusehen, was los ist?", sourceObjective = "To'kini möchte, dass Ihr mit Bah'Kini in Gundrak sprecht.", completion = "To'kini is' mein feiger Vater - er traut sich nicht so nahe an Gundrak heran... deshalb hat er mich geschickt!\n\nHier gibt's soviel Trollgeschichte. Wir dürf'n nich' zulassen, dass Gal'darah un' seine irren Anhänger sie auf ewig vor uns verstecken!", sourceObjectiveStatus = "unverified-source-field" }
quests[29837] = { id = 29837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilige Schriftrolle", description = "Die fremdartigen Markierungen auf diesem Pergament haben eine Eleganz an sich, zu der dieser Yoggtord und seine Bande gar nicht fähig wären.\n\nIhr vermutet, dass es wie alles andere auch, was diese Ho-zen besitzen, gestohlen ist.\n\nMöglicherweise hält sich der rechtmäßige Besitzer der Schriftrolle noch in der Nähe auf...", sourceObjective = "Bringt die unlesbare Schriftrolle zu Lehrensucher Cho.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[29838] = { id = 29838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzigartig", description = "Auf'n ersten Blick denkt ma', die Geschichte kenn' ich schon: Trolle zapf'n verbotene Energien an, weil sie die Wesen vernicht'n, die sie eigentlich anbeten sollt'n.\n\nWenn's stimmt, was ich so hör', dann haben sie 'nen besonderen Golem - einen, der anders is' als alle and'ren vor ihm!\n\nBring mir'n Stück von dem Golem zum Untersuchen, Mann.", sourceObjective = "Chronistin Bah'Kini möchte, dass Ihr ein Stück des Kolosses der Drakkari in Gundrak erbeutet.", progress = "Hast du mir ein Stück dieses Golems gebracht, Mann?", completion = "Ahh, ja Mann! Das ist es, wonach ich gesucht habe.\n\nHier, bitte schön - nimm dir was Schönes für den Ärger, den du hattest.", sourceObjectiveStatus = "unverified-source-field" }
quests[29839] = { id = 29839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzigartig", description = "Dem ganz'n Ärger hätte man aus'm Weg gehen können, wenn die Drakkari die Götter angebetet, anstatt umgebracht hätt'n.\n\nIch hab gehört, dass sie 'nen besonderen Golem haben, einen, in dem verbotene Energien stecken.\n\nBring mir ein Stück von dem Golem, Mann, damit wir von uns'ren Brüdern und Schwestern lernen können.", sourceObjective = "Tol'mar möchte, dass Ihr ein Stück des Kolosses der Drakkari in Gundrak erbeutet.", progress = "Hast du den Golem gefunden, Mann? Der muss da irgendwo sein.", completion = "Unglaublich! Sowas hab' ich noch nie geseh'n.\n\nGute Arbeit, Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[29840] = { id = 29840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Nachwelt", description = "Gundrak is' nich' mehr zu rett'n, Mann. Du weißt, dass ich Recht habe.\n\nWenn du den Mut dazu hast, such nach Geschichtstafeln, in denen steht, wieso das Reich der Drakkari gefall'n is'.\n\nVielleicht könn'n wir's eines Tages wieder aufbau'n.", sourceObjective = "Chronistin Bah'Kini in Gundrak möchte, dass Ihr 6 Geschichtstafeln der Drakkari sammelt.", progress = "Haste die Geschichtstafeln der Drakkari gefund'n, Mann?", completion = "Bin dir echt dankbar dafür, Mann.\n\nDie werd'n uns 'ne große Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[29841] = { id = 29841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschaffenheit des Landes [TEMP]", description = "Grah!!\n\nFür jeden dieser Schlammschleuderer, den wir ausschalten, springen zwei weitere aus dem Wald und nehmen seinen Platz ein. Ich möchte nicht, dass die anderen es schon erfahren, aber es ist offensichtlich, dass wir hier nicht lange durchhalten werden, {name}.\n\nIch muss hier bleiben und unseren letzten Besitz verteidigen. Erkundet Ihr die Gegend und sucht eine Lösung für unser Primatenproblem.\n\nGeht jetzt. Unsere Hoffnungen begleiten Euch...", sourceObjective = "Erkundet die Gegend.", sourceObjectiveStatus = "unverified-source-field" }
quests[29842] = { id = 29842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antworten suchen", description = "<Cho hört sich zuerst Eure Fragen an, bevor er spricht.>\n\nSo viel, über das man nachdenken muss, <Reisender/Reisende>...\n\nIhr müsst zuerst lernen, wie man fragt, bevor Euer Geist die Wahrheit erkennen kann.\n\nIch habe meine Meditation für heute beendet, aber meine Kerzen bleiben am Ring des Blutes.\n\nGeht dorthin. Leert Euren Geist. Wir sprechen uns wieder, wenn Ihr bereit seid, meine Worte zu hören.", sourceObjective = "Nutzt die Kerzen, um am Cairn des Blutes zu meditieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[29844] = { id = 29844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Nachwelt", description = "Das Land der Eistrolle is' nur noch'n Schatten seiner selbst.\n\nWenn du genug Mut aufbringst, dann such doch mal nach Geschichtstafeln, Mann. Da steht drin, wieso das Reich der Drakkari untergegang'n ist.\n\nEines Tages werd'n wir das Land vielleicht an 'ne neue Generation Frosttrolle weitergeb'n können.", sourceObjective = "Tol'mar in Gundrak möchte, dass Ihr 6 Geschichtstafeln der Drakkari sammelt.", progress = "Haste die Geschichtstafeln der Drakkari gefund'n, Mann?", completion = "Die Reiche von uns Trollen werd'n schon länger gespalten als es die and'ren Völker gibt, Mann.\n\nWir steh'n immer wieder aus den Ruinen auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[29847] = { id = 29847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Spuren des Diebs", description = "Unmittelbar hinter dieser Höhle liegt das Rabenholdtanwesen. Ihr müsst dort eindringen, ohne bemerkt zu werden!\n\n<Mostrasz belegt Euch mit einer Verzauberung.>\n\nGut - nun kann ich Euch auf Eurem Weg durch das Anwesen beobachten und mit Euch kommunizieren. Schleicht Euch hinein, findet das Ei und lasst Euch nicht erwischen...", sourceObjective = "Dringt in das Rabenholdtanwesen ein und findet das verschwundene Schwarzdrachenei.", completion = "Werdet Ihr mit mir zusammenarbeiten?\n\nGut. Sehr gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[29848] = { id = 29848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Behüterin", description = "Ich würde mein Leben mit Freuden für die Schöpfer oder ihre Wesen hingeben.\n\nSeit Lokens Verrat scheint es mir jedoch, als habe sich ganz Ulduar gegen die Welt verschworen. Vor allem die Maid der Trauer leidet entsetzlich unter ihren neuen Befehlen.\n\nBitte schenkt ihr Frieden und bringt mir eine ihrer Tränen.", sourceObjective = "Kaldir Eisenbann in den Hallen des Steins möchte, dass Ihr der Maid der Trauer Frieden schenkt und eine Kristallträne der Trauer beschafft.", progress = "Ich wünschte, es gäbe einen anderen Weg, aber nur der Tod kann die Maid jetzt noch erlösen.", completion = "<Kaldir starrt einen Moment schweigend in den Kristall.>\n\nKein Wesen hat das Leid je so gespürt wie die Maid der Trauer.\n\nDaran sollten wir denken, während wir unseren Kampf gegen Loken fortsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29850] = { id = 29850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korrupte Konstrukte", description = "Die Eisenzwerge haben damit begonnen, gewaltige Steinkonstrukte zu erschaffen, die sie, so fürchte ich, bald als mächtige Waffen einsetzen werden.\n\nIhr müsst unbedingt ihren Aufseher Krystallus und die dunklen Runenriesen, die bereits in den Hallen aufgetaucht sind, besiegen. Beeilt Euch, bevor es zu spät ist!", sourceObjective = "Kaldir Eisenbann in den Hallen des Steins möchte, dass Ihr Krystallus und 3 dunkle Runenriesen tötet.", completion = "Gut gemacht, {race}.\n\nJede Waffe, die wir Loken abnehmen können, hilft unserem eigenen Feldzug.", sourceObjectiveStatus = "unverified-source-field" }
quests[29851] = { id = 29851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion des Turniers", description = "Dank dieses Turniers kommen wir unserer letzten Konfrontation mit dem Lichkönig immer näher.\n\n{name}, kämpft tapfer und ehrenhaft. Die Kämpfer hier haben sich hier zu unser aller Wohl versammelt.\n\nGemeinsam werden wir Arthas aufhalten!", sourceObjective = "Hochlord Tirion Fordring hat Euch beauftragt, die Prüfung des Champions zu vollenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29860] = { id = 29860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegensätze", description = "Ich werde offen mit Euch sprechen, <kleiner/kleine:r> {race}. Mein Volk ist nicht mehr das gleiche, seit unsere Verbindung zu Thorim abgerissen ist.\n\nVolkhan wird nicht ruhen, bis er oder wir nicht mehr existieren. Wir wollen nur Frieden, doch es scheint, als läge unsere einzige Hoffnung im Krieg.", sourceObjective = "Sturmbote Eljrrin in den Hallen der Blitze möchte, dass Ihr Volkhan besiegt.", completion = "Volkhan wird mein Volk nicht mehr in seinen Träumen heimsuchen.\n\nMacht weiter wie bisher, kleiner {race}. Irgendwann wird mein Volk Thorim schon vergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29861] = { id = 29861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit allen Mitteln!", description = "Loken wird fallen, egal, wie.\n\nDie Ehre und der Ruhm seiner Niederlage soll Euch gebühren.\n\nKehrt zu mir mit seiner gespaltenen Zunge zurück und verdient Euch meinen ewigen Dank.", sourceObjective = "Sturmbote Eljrrin in den Hallen der Blitze möchte, dass Ihr Loken besiegt. Dann sollt Ihr mit Lokens Zunge zu Sturmbote Eljrrin zurückkehren.", progress = "Habt Ihr Gerechtigkeit über Loken gebracht?", completion = "Dieser widerliche Wurm ist tot?\n\nIhr seid wahrhaft ein Segen für mein Volk, kleiner {race}. Bitte nehmt dieses Geschenk als Anerkennung Eurer loyalen Freundschaft.", sourceObjectiveStatus = "unverified-source-field" }
quests[29862] = { id = 29862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg frei machen", description = "Lokens Streitkräfte bereiten sich auf den Krieg vor. Sie rechnen allerdings nicht damit, selbst angegriffen zu werden.\n\nWir müssen rasch zuschlagen. Vernichtet General Bjarngrim und seine Armee, bevor sie alles Leben auf Azeroth gefährden!", sourceObjective = "Sturmbote Eljrrin in den Hallen der Blitze möchte, dass Ihr 3 sturmgeschmiedete Heiler, 3 sturmgeschmiedete Taktiker und General Bjarngrim tötet.", completion = "Nur wenige außer uns werden je davon erfahren, aber Ihr habt an diesem Tag die Welt gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29863] = { id = 29863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmbote Eljrrin", description = "Ich habe einen Abgesandten in die Hallen der Blitze geschickt, um Loken zu bedrängen.\n\nEr könnte zweifellos Hilfe gebrauchen, wenn man die Stärke von Lokens Armeen bedenkt. Unterstützt ihn so gut Ihr könnt, damit wir den Verräter endlich besiegen können.", sourceObjective = "König Jokkum möchte, dass Ihr die Hallen der Blitze betretet und mit Sturmbote Eljrrin sprecht.", completion = "Wir haben nicht viel Zeit. Loken bereitet sich bereits auf den Krieg vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[29864] = { id = 29864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wurzel des Übels", description = "Wir tun alles, um die Verluste, die uns die Kriegsmaschinerie der Geißel zufügt, zu minimieren.\n\nDie Vrykul gefährden diese Mission, indem sie sich willentlich den Truppen des Lichkönigs anschließen.\n\nBitte, <edler Held/edle Heldin>, besiegt ihre spirituelle Anführerin Svala, bevor sie ihr Volk in die ewigen Schatten führt!", sourceObjective = "Argentumbeichtpatin Blondlocke möchte, dass Ihr Svala Grabesleid tötet.", completion = "Jeder Soldat, den wir der Geißel vorenthalten, bedeutet mehr als nur ein gerettetes Leben.\n\nDanke.", sourceObjectiveStatus = "unverified-source-field" }
quests[29865] = { id = 29865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seidenwaldstraße", description = "Westlich von hier befindet sich die Seidenwaldstraße. Es ist mittlerweile sehr gefährlich, sie zu bereisen, weil die Spinnen dort immer bösartiger, um nicht zu sagen \"gefräßiger\", geworden sind.\n\nIch würde sie ja herzlich gern selbst ausrotten, aber jemand muss ja den Nudelladen... öh... verteidigen...\n\nAlso, <junger Held/junge Heldin>, geht und zerquetscht diese Biester! Wenn Ihr Erfolg habt, werde ich Euch vielleicht mit einer meiner Heldensagen belohnen.\n\nUnd mit einer Bezahlung, versteht sich.", sourceObjective = "Zerquetscht 8 Seidenholzpirscher.", completion = "Was für ein edler Held Ihr doch seid. Ihr erinnert mich an mich selbst, als ich noch jünger und weniger gut aussehend war.", sourceObjectiveStatus = "unverified-source-field" }
quests[29866] = { id = 29866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seidenernte", description = "Ah, willkommen, <Reisender/Reisende>. Ich würde gern Eure Dienste in Anspruch nehmen!\n\nSyra Zapfgold ist auf der Suche nach etwas Seide. Ich selbst hasse ja Seide, weil sie sich immer in meinem Fell verfängt.\n\nAber ich möchte sie wirklich gern beeindrucken.\n\nWenn Ihr mir etwas Seide aus dem Seidenwald westlich von hier bringen könnt, werde ich Euch gerne dafür bezahlen.", sourceObjective = "Sammelt 7 makellose Seidenstränge.", progress = "Habt Ihr den Seidenwald gefunden?", completion = "Oh, vielen herzlichen Dank! Die sind perfekt!\n\nIch hoffe, Ihr habt Euch nicht so darin verfangen wie ich sonst immer.\n\nIch werde jetzt gleich zu Syra gehen und sie ihr geben!", sourceObjectiveStatus = "unverified-source-field" }
quests[29871] = { id = 29871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schlaue Ashyo", description = "Ich weiß nicht, wo der schlaue Ashyo den Titel \"schlau\" herhat. Alle Jinyu sind nämlich schlau, und ich würde nicht behaupten, dass er klüger als die meisten anderen ist.\n\nEigentlich ist das Gegenteil der Fall.\n\nZumindest ist er ein fähiger Kämpfer. Im Tiankloster war er gut genug, um für unsere Trainingsmission ausgewählt zu werden.\n\nWenn Ihr ihm bei der Suche nach dem verborgenen Meister helfen wollt, findet Ihr ihn an der nördlichen Grenze des Tals.", sourceObjective = "Findet den schlauen Ashyo.", completion = "Wo habe ich Euch schon einmal gesehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29872] = { id = 29872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lin Zartpfote", description = "Lin hat mehr Talent, als sie selbst glaubt. Sie hat eine starke Faust, aber einen schwachen Geist. Mit etwas mehr Selbstvertrauen könnte sie besser sein als wir alle.\n\nVielleicht gewinnt sie bei ihrer Reise in den Westen an Selbstsicherheit. Wahrscheinlich ist sie gerade jetzt unterwegs nach Steinpflug. Haltet sie auf und redet mit ihr, wenn Ihr in jenem Teil des Tals seid.", sourceObjective = "Findet Lin Zartpfote.", completion = "Oh, Ihr seid es!\n\nNein, ich habe den verborgenen Meister noch nicht gefunden. Wahrscheinlich habe ich hier draußen nur meine Zeit vergeudet.\n\n<Seufz...>", sourceObjectiveStatus = "unverified-source-field" }
quests[29873] = { id = 29873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ken-Ken", description = "Achso... Ken-Ken. Der Ho-zen.\n\nIch selbst bin beeindruckt, dass er in seiner Ausbildung so weit gekommen ist. Er hat ein Hirn zwischen den Ohren, was mehr ist, als man über die meisten seines Volks sagen kann.\n\nEr sagte, er wollte Richtung Osten, und da wir bereits weit im Osten des Tals sind, kann ich mir nicht vorstellen, dass er allzu weit von hier entfernt sein kann. Sucht nach ihm bei Zhus Wacht in der Krasarangwildnis, den Weg runter in Richtung Süden. Seht nach, was er gefunden hat.", sourceObjective = "Sucht Ken-Ken.", completion = "Dieser Ort... er... er so TRAURIG!\n\nKen-Ken noch nie einen so traurigen Ort gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29874] = { id = 29874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kang Dornstab", description = "Kangs Stolz wird regelmäßig zu Vermessenheit, was ihn oft auf gefährliche Pfade führt. Sein momentaner Pfad ist eben solch ein gefährlicher - er führt tief in die Krasarangwildnis.\n\nIch würde normalerweise <einen Fremden/eine Fremde> nicht um einen Gefallen bitten, aber... würdet Ihr Euch vergewissern, dass es ihm gut geht? Es wäre eine Erleichterung für mich, zu wissen, dass <ein mutiger/eine mutige:r> {race} nach ihm sieht.", sourceObjective = "Sucht Kang Dornstab.", completion = "Ich bin ziemlich sicher, dass diese Siedlung vor ein paar Wochen noch nicht hier war. Wo sind diese Leute hergekommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29875] = { id = 29875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kang Dornstab", description = "Kangs Stolz wird regelmäßig zu Vermessenheit, was ihn oft auf gefährliche Pfade führt. Sein momentaner Pfad ist eben solch ein gefährlicher - er führt tief in die Krasarangwildnis.\n\nIch würde normalerweise <einen Fremden/eine Fremde> nicht um einen Gefallen bitten, aber... würdet Ihr Euch vergewissern, dass es ihm gut geht? Es wäre eine Erleichterung für mich, zu wissen, dass <ein mutiger/eine mutige:r> {race} nach ihm sieht.", sourceObjective = "Sucht Kang Dornstab.", completion = "Ich bin ziemlich sicher, dass diese Siedlung vor ein paar Wochen noch nicht hier war. Wo sind diese Leute hergekommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29877] = { id = 29877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundwissen mangelhaft", description = "Shed-Ling - die tun mehr, als nur unsere Nahrung fressen. Die wollen ihre eigenen Höfe gründen. Das Problem is' nur... Das sind alle verfiddelt taube Nüsse.\n\nDu glaubst Muno nicht? Gestern Nacht sind sie in unsere Werkzeugschuppen eingebrochen... ha'm das meiste rausgeklaut. Als wir aufgewacht sind, fanden wir Harken und Schubkarren im Boden.\n\nDie wollten das BEWÄSSERN. Die wollten SCHUBKARREN ANBAUEN.\n\nBitte grabe unsere Sachen aus, wenn du dort draußen bist.", sourceObjective = "Grabt 7 Landwirtschaftswerkzeuge aus.", progress = "Mann, diese Shed-Ling sind völlig hohl.", completion = "Danke. Vielleicht kann ein Ho-zen jetzt endlich mal seiner verfiddelten Arbeit nachgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29879] = { id = 29879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Ganzen verschlungen", description = "Zurück zu Eurem Dilemma.\n\nIch glaube, Ihr könnt eurem Volk helfen, eine Beziehung zu unseren Ho-zen aufzubauen, so wie es auch unser Volk getan hat.\n\nDer Pfad hinter mir wird Euch zu einem See führen, aus dem die Ho-zen ihre Fische beziehen.\n\nJedes Jahr zu dieser Zeit gibt es in dem See furchterregende Biester, denen viele hungrige Ho-zen zum Opfer fallen.\n\nWenn Ihr einige der Opfer retten und ein paar Fische sammeln könntet, würden die Ho-zen Euch vielleicht freundlicher gesinnt sein.", sourceObjective = "Befreit 5 Ho-zen aus dem Inneren vollgefressener Krokilisken und sammelt 5 Bachsaiblinge am Kittitatasee.", progress = "Nappel hat Glitschis... für mich!?", completion = "Nappel hat Ho-zen gerettet? Und Glitschis gebracht?\n\nHmm, vielleicht Nappel doch nicht so böse.\n\nTuki Tuki hat Djuuk Uukem sowieso noch nie gemocht...", sourceObjectiveStatus = "unverified-source-field" }
quests[29881] = { id = 29881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die perfekte Farbe", description = "Wie Ihr gesehen habt, gibt es in diesem Hain wunderschöne rosafarbene Blüten. Wenn die Blütenblätter welken, wird der Ton dunkler und verblasst.\n\nWärt Ihr so freundlich, mir einige frisch abgefallene Blütenblätter zu bringen? Nur die, die gerade herabgefallen sind, haben genau die Farbe, die ich brauche.\n\nDaraus kann ich eine atemberaubende Tinte herstellen. Werdet Ihr mir helfen?", sourceObjective = "Sammelt 8 frisch gefallene Blütenblätter.", progress = "Wenn ein Blütenblatt abfällt, bleibt nur wenig Zeit, in der es für den perfekten Farbton verwendet werden kann.", completion = "Ah! Ihr habt ein gutes Auge für Farben. Daraus lässt sich ein hervorragendes Pigment herstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29882] = { id = 29882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feder aus Stacheln", description = "Für den perfekten Pinselstrich braucht man auch das richtige Werkzeug. Meine eigenen Pinsel lassen sich nicht mehr reparieren, die Borsten sind so unnachgiebig wie Ho-zen-Haar geworden.\n\nHabt Ihr die Wespen im Arboretum gesehen? Aus ihren Stacheln kann man Schreibfedern herstellen, die sich für jeden Schärfegrad eignen.\n\nKönntet Ihr mir bitte einige besorgen?", sourceObjective = "Sammelt 6 Wespenstachel von Obstgartenwespen.", progress = "Habt Ihr einige Stachel gefunden? Normalerweise würde ich einen Mönch darum bitten, aber die scheinen alle beschäftigt zu sein.", completion = "Vielen Dank. Daraus lassen sich schöne Schreibfedern herstellen. Hier habt Ihr etwas für Eure Mühe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29883] = { id = 29883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Perlflossenproblem", description = "Ich habe nachgedacht.\n\nWir sind hier von aller Versorgung abgeschnitten und weit weg von zu Hause.\n\nZwar scheinen uns diese Perlflossen-Jinyu zu misstrauen, aber sie wirken nicht feindselig.\n\nWenn wir sie davon überzeugen können, dass wir ihre Freunde sind, könnte sich ein Bündnis zwischen unseren Völkern als sehr wertvoll erweisen.\n\n{name}, Ihr müsst mit den Jinyu im Dorf sprechen.\n\nÜberzeugt ihre Anführer, dass sie uns nicht fürchten müssen und dass wir nichts als Frieden wollen.", sourceObjective = "Sprecht mit dem Ältesten Lusshan, Perlenhüter Fujin, Ausbilder Scharffinne und Ot-Temmdo im Dorf der Perlflossen.", completion = "Anscheinend habt Ihr einen guten Eindruck gemacht.\n\nIch bin beeindruckt, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[29885] = { id = 29885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wegzehrung", description = "Wir haben keine Zeit, um hier zu warten, bis sich der Admiral erholt hat.\n\nSully und ich werden im Norden nach Anduin suchen, aber wir benötigen Vorräte für die Reise.\n\nIm See hier wimmelt es von Tieren, die wir jagen dürfen.\n\nSammelt einige Vorräte, während Sully und ich die letzten Vorbereitungen treffen.", sourceObjective = "Besorgt 6 Schildkrötenflanken.", progress = "Die Zeit ist knapp. Mit jeder Stunde, die wir verlieren, kann der Weiße Bauer weiter weg sein.\n\nWo sind die Vorräte, um die ich gebeten habe?", completion = "Das dürfte genug sein, {name}. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[29886] = { id = 29886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zenheilung", description = "Euer Freund Taylor ist in einem schlechten Zustand. Seine Wunden sind mit Ho-zen-Gift verunreinigt worden, das sehr schwer zu heilen ist.\n\nZum Glück hat mein Volk, das seit vielen Generationen gegen die Ho-zen kämpft, Medizin gegen solche Wunden entwickelt.\n\nDie Blumen, die auf der Oberfläche des Perlsees rings um unser Dorf wachsen, werden für das Gegenmittel benötigt.\n\n{name}, geht schnell und bringt mir ein paar Blüten. Das Leben Eures Admirals steht auf dem Spiel.", sourceObjective = "Sammelt 6 Zenlotus.", sourceObjectiveStatus = "unverified-source-field" }
quests[29887] = { id = 29887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Instrumente des Ältesten", description = "Oje, oje... Der Älteste darf es nicht erfahren!\n\nIch muss bei der Flucht die zeremoniellen Instrumente des Ältesten vergessen haben.\n\nAber... die Mondwasserzuflucht ist jetzt voller Ho-zen!\n\nWas bin ich nur für ein Perlenhüter, dass ich sie einfach zurücklasse?\n\n<Der alte Jinyu vergräbt sein Gesicht in den Händen.>\n\nKönnt Ihr mir wohl helfen?", sourceObjective = "Holt den Stab des Wassersprechers, die zeremoniellen Roben, die Jadekrone und die Rosenholzperlen von den Langfingern der Schlingschwänze zurück.", progress = "Der Älteste ist ein Wassersprecher. Er spricht mit dem Wasser, und es antwortet.", completion = "Ihr habt alles gefunden? Oh, den Geistern des Wassers sei Dank!\n\nIhr habt mir die Schwanzflosse gerettet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29888] = { id = 29888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Lehrensucher aufsuchen", description = "Mir ist aufgefallen, dass Ihr und Eure Leute verzweifelt nach Eurem Prinzen Anduin sucht.\n\nIch kenne jemanden, der Euch vielleicht helfen kann, ein Lehrensucher der Pandaren, der dieses Land besser kennt als jeder andere. Ich weiß nicht, wie er Euch empfangen wird, aber er wird Euch mit ziemlicher Sicherheit genauso neugierig begegnen wie Ihr ihm!\n\nDer Lehrensucher lebt im Wald im Südwesten. Sagt ihm, dass Euch die Perlflossen schicken.", sourceObjective = "Findet Lehrensucher Cho im Pavillon des Träumers im Jadewald.", completion = "Ihr seht Euch bei dem leeren Haus um.\n\nEs scheint, als wäret Ihr am richtigen Ort, doch vom Bewohner ist nichts zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29889] = { id = 29889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geborgtes Gebräu", description = "Der Flasche auf dem Tisch entströmt ein köstlicher Duft.\n\nEin kleiner Schluck kann doch nicht schaden, oder?", sourceObjective = "Kostet das köstliche Gebräu.", completion = "Ich habe gehört, dass solche wie Ihr an unsere Strände gespült worden sind, aber ich hätte nicht erwartet, dass ich einen von Euch direkt vor meiner Haustür finden würde! Was bringt Euch hierher, Fremder?\n\n<Ihr erklärt dem Pandaren Eure Suche nach Prinz Anduin und beschreibt ihm den Jungen.>\n\nSehr interessant! Und die Perlflossen haben Euch zu mir geschickt, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[29890] = { id = 29890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die innere Mitte finden", description = "Das Traumgebräu ist vollendet! Wenn Ihr es dieses Mal trinkt, müsst Ihr die Visionen, die Ihr seht, mit einem inneren Fokus betrachten.\n\nFolgt mir zu meiner Pagode und ich werde Euch lehren, wie Ihr die innere Ruhe erreichen könnt, die uns Pandaren so wichtig ist.\n\nEuer aufgewühltes Gemüt wird Euch viele Ablenkungen präsentieren, doch vergesst nicht, Euch auf Eure innere Mitte zu konzentrieren!", sourceObjective = "Meditiert mit Lehrensucher Cho im Pavillon des Träumers im Jadewald.", completion = "Wie habt Ihr mich gefunden?\n\n<Anduin hört zu, wie Ihr die durch das Traumgebräu hervorgerufene Vision beschreibt.>\n\nDas ist ja erstaunlich! Genau das ist vor einigen Tagen passiert. Seitdem haben wir uns versteckt gehalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29891] = { id = 29891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein starkes Gebräu", description = "Für die Herstellung des Traumgebräus benötigen wir mehrere Zutaten.\n\nUm die Stärke zu verbessern, brauche ich eine Zutat von einer schaurigen Kreatur, dem legendären Nebelschrecken.\n\nAngeblich erscheint diese Kreatur nur dort, wo der Nebel am dichtesten ist.\n\nIm Norden und Osten findet Ihr kleinere Nebelkrabbler in den Sümpfen. Vernichtet diese Kreaturen, bis der Nebelschrecken erscheint, und bringt mir dann sein Herz.", sourceObjective = "Tötet Nebelkrabbler, bis ein Nebelschrecken erscheint, und nehmt ein Nebelschreckenherz an Euch.", progress = "Die Nebel scheinen einen eigenen Willen zu besitzen, was?", completion = "Das ist ein unglaubliches Exemplar! Ich bin überrascht, dass Ihr tatsächlich erfolgreich wart.", sourceObjectiveStatus = "unverified-source-field" }
quests[29892] = { id = 29892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Körper", description = "Der Körper eines Gebräus ist wichtig und bleibt allzu häufig unbeachtet.\n\nUm die perfekte Konsistenz zu erhalten, benötige ich makellose Augen von Sumpfkrokilisken aus dem Osten.\n\nGebt Acht. Diese Kreaturen sind ziemlich grausam.", sourceObjective = "Sammelt 5 makellose Krokiliskenaugen von Sumpfkrokilisken.", progress = "Passt im Sumpf gut auf Euch auf, mein neuer Freund.", completion = "Gibt es da, wo Ihr herkommt, auch Krokilisken?", sourceObjectiveStatus = "unverified-source-field" }
quests[29893] = { id = 29893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Färbung", description = "Das Auffälligste am Traumgebräu ist seine leuchtende traumartige Farbe.\n\nIm Osten könnt Ihr schillernde Bernfliegen finden. Ich benötige ihre Flügel, um die letzte Leuchtfarbe des Gebräus herzustellen.\n\nNehmt dieses Messer und schneidet damit 8 Flügel ab.", sourceObjective = "Sammelt 8 Bernfliegenflügel.", progress = "Habt Ihr die Zutaten besorgt? Es ist fast an der Zeit, das Traumgebräu herzustellen.", completion = "Eine wunderschöne Farbe, seltene Transparenz, schimmernd, aber nicht funkelnd… Sie sind hervorragend.\n\nSo langsam erkenne ich ein großes Potenzial in Euch, Fremdling.", sourceObjectiveStatus = "unverified-source-field" }
quests[29894] = { id = 29894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister des Wassers", description = "Unser Krieg gegen die Ho-zen scheint endlos zu sein, und die Zukunft unseres Stammes ist ungewiss.\n\nDarum hat unser Wassersprecher beschlossen, um die Weisheit des Wassers zu ersuchen.\n\nDer Älteste Lusshan wartet. Bitte bringt ihm die Instrumente, damit sie beginnen können.", sourceObjective = "Sprecht mit dem Ältesten Lusshan und werdet Zeuge der Wassersprechzeremonie.", progress = "<Die Augen des Ältesten verklären sich. Sein Blick wird nach innen gekehrt, in Richtung des Wissens, das er gewonnen hat.>", completion = "Ich habe die Vision gesehen, {name}. Was hat sie Eurer Meinung nach zu bedeuten?\n\nEs ist offensichtlich, dass Ihr eine Rolle darin spielt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29895] = { id = 29895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Spur des Weißen Bauern", description = "Der Mantel ist zwar zerschlissen und zerrissen, aber die feine Machart und das königliche Wappen sind unverkennbar.\n\nIhr solltet ihn Eurem Kommandanten der Allianz zeigen.", sourceObjective = "Zeigt Admiral Taylor im Dorf der Perlflossen im Jadewald den Mantel.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[29898] = { id = 29898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heiliges Wasser", description = "Ich bin dankbar dafür, dass Ihr den weiten Weg gemacht habt, um mich zu retten, aber Ren ist schwer verletzt.\n\nDer alte Pandaren hatte keinen Grund, mir zu helfen, und doch hat er für mich sein Leben riskiert.\n\nVor Ausbruch des Fiebers erwähnte er, dass es in der Höhle am Fuße des Hügels heilendes Wasser gäbe.\n\nEs ist gefährlich, aber ich würde alles tun, um meinem Freund zu helfen. Werdet Ihr mir dabei helfen, das Wasser zu holen?", sourceObjective = "Holt heilendes Wasser aus den vier heiligen Schalen in der Höhle der Trauer.", progress = "Vielleicht könnte ich etwas von diesem heilenden Wasser mit nach Sturmwind nehmen.", completion = "Das heilende Wasser müsste Rens Fieber kurzfristig senken, aber das ist keine dauerhafte Lösung.\n\nVielen Dank, {class}. Wir haben ihm wenigstens etwas mehr Zeit verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[29899] = { id = 29899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhet in Frieden", description = "Die Geister... die Höhlenbewohner... sie schreien vor Schmerzen... \n\nGefangen... in dieser Welt... können sich nicht... zur nächsten bewegen.\n\nIch... werde verrückt... solange ich… ihre Schreie höre... \n\nBitte… bringt sie... zum Schweigen.", sourceObjective = "Tötet 6 gepeinigte Geister.", completion = "Vielen Dank… Ich bin… froh… da ich weiß… dass die Geister… Frieden gefunden haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29900] = { id = 29900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine alte Legende", description = "Mein Vater hat sein Leben dem Studium des Tals der Ewigen Blüten gewidmet.\n\nDas Tal ist ein mystischer Ort, vollkommen abgeschieden nach der Revolution der Pandaren vor 12.000 Jahren. Wir wissen so wenig darüber.\n\nMein Vater ist einigen Hinweisen bis zu der Höhle am Fuße des Hügels gefolgt. Darin befindet sich ein sehr altes Gedicht, das als der Gesang des Tals bekannt ist, aber er kann es nicht an sich nehmen. Es wird von einer Art Geist der Ahnen bewacht.\n\nWenn Ihr ohnehin in diese Richtung wollt, könnt Ihr es ihm dann vielleicht bringen?", sourceObjective = "Holt den Gesang des Tals aus der Höhle der Trauer.", progress = "Habt Ihr… die Schriftrolle gefunden?", completion = "Oh… Das ist das Gedicht! Habt Ihr… es gelesen? Wo liegt… das Tal?", sourceObjectiveStatus = "unverified-source-field" }
quests[29901] = { id = 29901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anduins Entscheidung", description = "Ihr habt für die Freunde des Prinzen getan, was Ihr könnt.\n\nIhr habt Eure Mission erfüllt und den Weißen Bauern gefunden: Prinz Anduin. Admiral Taylor und die anderen SI:7-Agenten werden darauf brennen, den Jungen in Gewahrsam zu nehmen.\n\nEs ist Zeit, nach Hause zurückzukehren.", sourceObjective = "Sagt Anduin, dass es Zeit ist, nach Hause zurückzukehren.", completion = "Er hat WAS gemacht?!?\n\nEr hat Glück, dass ich ihn noch nicht gefunden habe, denn sonst hätte ich ihm den Kopf abgerissen!\n\nWas denkt er sich nur... dieses Tal zu suchen... Das ist kein Verhalten, das eines Prinzen würdig ist!\n\nHätten wir nicht Dringenderes zu erledigen, würde ich unsere gesamte Flotte hinter ihm herschicken!", sourceObjectiveStatus = "unverified-source-field" }
quests[29903] = { id = 29903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Passt perfekt", description = "Der Älteste Lusshan und ich sind uns einig, dass wir zusammenarbeiten sollten.\n\nWir werden unser überlegenes militärisches Wissen und unsere Waffen mit den Perlflossen teilen.\n\nDafür haben wir einen mächtigen Verbündeten, falls wir erneut auf die Horde treffen.\n\nNehmt diese Kiste mit Ausrüstungsgegenständen und Waffen. Ihr müsst durch das Dorf gehen und die Jinyu entsprechend ihrer Fähigkeiten mit Waffen ausstatten.", sourceObjective = "Sprecht mit den Aqualythen der Perlflossen und stattet sie mit der richtigen Ausrüstung aus.", progress = "Die Jinyu sind unterschiedlich begabt. Es liegt an uns, ihre Stärken herauszufinden.", completion = "Gut. Jetzt können die Bastarde von der Horde ruhig wieder auftauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29904] = { id = 29904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Größere Fische", description = "Ich habe eine Gruppe aus vielversprechenden Schülern der Perlflossen zusammengestellt, die Kampferfahrung brauchen.\n\nGeht mit ihnen in den Nordosten in die Bambuswildnis und erlegt alle Tiere, auf die Ihr trefft.\n\nKommt erst zurück, wenn sie bereit für den Kampf sind.", sourceObjective = "Bildet die Adepten der Perlflossen aus, indem Ihr 24 Tiere in der Bambuswildnis erlegt.", progress = "Wie machen sich die Schüler?", completion = "Eure Schüler sind vor Kurzem zurückgekehrt. Ich konnte es kaum glauben! Das waren nicht mehr dieselben Jinyu, mit denen Ihr aufgebrochen seid.\n\nHervorragende Arbeit, {class}. Das hätte ich nicht besser machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[29905] = { id = 29905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie brennen", description = "Vorhutsspäher haben gemeldet, dass sich die Ho-zen in den Schlingschwanzgruben mit Verstärkung aus den Stämmen im Norden vereinen.\n\nUnsere Truppen machen sich am Kamm im Nordwesten kampfbereit und warten nur noch auf Euch.\n\nJetzt können wir ihnen zeigen, aus welchem Holz wir geschnitzt sind, und sie endgültig vernichten.", sourceObjective = "Vernichtet 15 Flotsch-Verstärkungen oder Schlingschwanz-Rekruten.", completion = "Das Wasser hatte in Bezug auf Euch recht, {name}. Dank Eurer Bemühungen hat dieses Dorf eine Zukunft. Wir werden nie vergessen, was Ihr uns gelehrt habt, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29906] = { id = 29906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carpe Diem", description = "Auch wenn die Ho-zen unkoordiniert erscheinen, steckt eine Ordnung hinter dem Chaos. Ihr Anführer, Häuptling Gukgut, ist der gerissene Lenker ihrer Angriffe.\n\nEr organisiert sie bei der großen Grube im Ho-zen-Lager im Nordwesten.\n\nSchlagt jetzt zu und zeigt keine Gnade, {name}, denn das würde er auch nicht tun.", sourceObjective = "Vernichtet Häuptling Gukgut.", completion = "Ohne ihren Anführer wird bei den Ho-zen erneut das Chaos ausbrechen.\n\nHeute genießen wir unseren Sieg! {name}, Ihr kamt als ein Fremder zu uns, doch Ihr verlasst uns als Freund.\n\nVon jetzt an seid Ihr hier außerordentlich geschätzt - als Freund und Verteidiger des Perlflossenstammes.", sourceObjectiveStatus = "unverified-source-field" }
quests[29907] = { id = 29907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chen und Li Li", description = "Meine Nichte und ich sind neu hier in Pandaria. Genau wie Ihr vermutlich. Wir kommen von der Wandernden Insel und sind nur zu Besuch hier. Eigentlich wissen wir gar nicht, wohin wir gehen wollen.\n\nAuf dem Hof dort könnten wir uns doch ausruhen und etwas trinken. Was meinst du, Li Li?\n\nMöchtet Ihr uns nicht vielleicht ein Stück des Weges begleiten, {race}?", sourceObjective = "Folgt Chen Sturmbräu zu Pangs Hof.", completion = "Herzlich willkommen, liebe Besucher! Möchtet Ihr die Rüben meines Sohnes probieren? Oder vielleicht ein paar Schweine kaufen?\n\nBitte fühlt Euch ganz wie zu Hause. Ich habe hier jede Menge Platz.", sourceObjectiveStatus = "unverified-source-field" }
quests[29908] = { id = 29908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schier unendliches Ärgernis", description = "Ich muss mich für den Zustand hier entschuldigen. Die Shed-Ling, diese kaninchenartigen Kreaturen vom Fuße der Berge, sind immer weiter auf den Hof meiner Familie vorgedrungen und haben unsere Erntepflanzen, die übrigens normalerweise viel größer und viel leckerer sind, geschädigt.\n\nIch bin kein Soldat... Aber Ihr seht aus wie einer! Könntet Ihr nicht ein paar dieser Shed-Ling von unserem Land vertreiben?", sourceObjective = "Tötet 8 Raffzahn-Shed-Ling, Werkzeugdiebe oder Unruhestifter. Tötet dann 18 Raffzahnnervensägen.", completion = "<Pang untersucht die nähere Umgebung seines Hofes.>\n\nTja, sie sind zwar nicht ALLE weg, aber zumindest sind es jetzt weniger. Und sie halten auch ihre Ohren nicht mehr ganz so hoch.\n\nIch glaube, sie haben Angst vor Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29909] = { id = 29909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geringe Rübenausbeute", description = "Ich weiß Eure Hilfe wirklich sehr zu schätzen, {name}. Und ich hätte noch eine weitere Aufgabe für Euch.\n\nMein Sohn, Ang, betreibt einen kleinen Hof am Fuße dieses Hügels. Er hätte mir heute morgen ein paar Früchte und etwas Gemüse bringen sollen, aber er ist bis jetzt noch nicht aufgetaucht.\n\nWürdet Ihr vielleicht dort runtergehen und mal nachsehen, was da los ist?", sourceObjective = "Findet Ang Donnerfuß.", completion = "Was? Wer seid...? Mein Vater hat Euch geschickt?\n\nPah... Er kann ja manchmal so neugierig sein. Ich habe hier alles unter Kontrolle.", sourceObjectiveStatus = "unverified-source-field" }
quests[29910] = { id = 29910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Miese Murmler", description = "Ich bin heute morgen losgegangen, um meinem Vater beim Kampf gegen die Shed-Ling zuzusehen. Und als ich zurückkam, war der Hof voller Murmeltiere!\n\nIch will sie gar nicht töten, aber wir müssen sie trotzdem loswerden. Hey, ich hab' eine Idee! Wir könnten doch ihre Baue verschließen!\n\nStopft etwas Dreck in die Löcher, damit sie nicht mehr auf dem Gelände unseres Hofes rauskommen.", sourceObjective = "Vertreibt 6 mollige Murmeltiere vom Donnerfußhof und verschließt 6 Murmeltierbaue.", progress = "Die Murmeltiere werden sich nicht darüber freuen, dass Ihr ihre Baue verschließt.", completion = "Ich danke Euch, guter Mann! Jetzt kann ich mich wieder meinen Pflichten widmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29911] = { id = 29911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Praktisch perfekte Produkte", description = "Bitte, {name}. Das wird meinem Vater gefallen.\n\nDanke nochmals für Eure Hilfe mit den Shed-Ling.", sourceObjective = "Bringt die Kiste mit frischem Obst und Gemüse zu Pang Donnerfuß.", progress = "Rieche ich da etwa Rüben?", completion = "Ho ho! Na, so etwas sehe ich gerne!", sourceObjectiveStatus = "unverified-source-field" }
quests[29912] = { id = 29912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fantastisches Fräulein Fanny", description = "Der Großteil dieses Gemüses wird zwar verkauft, aber etwas davon möchte ich für meine Familie behalten. Insbesondere mein Neffe Liang braucht etwas zum Füttern seiner Schweine.\n\nLeider wimmelt es auf dem Weg zu Liangs Hof nur so vor Raffzahn-Shed-Ling. Wir müssen Fräulein Fanny um Hilfe bitten.\n\nBringt etwas von dem Essen, das wir gesammelt haben, zu Fräulein Fanny, die neben meinem Haus steht. Bittet sie dann - NETT! - darum, es zu Liangs Hof zu befördern.", sourceObjective = "Bringt Angs riesige rosa Rübe, Angs Sommerwassermelone und Pangs besonders scharfen Tofu zu Fräulein Fanny, und bittet sie darum, sie zu befördern. Das Essen muss zum Gehöft Donnerfuß gebracht werden.", completion = "Wie ich sehe, habt Ihr das Essen vom Hof meines Onkels hierher geschickt. Vielen Dank.\n\nMeine Schweine sind wählerisch, aber diese Rüben und Melonen gehören zu ihrem Lieblingsessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29913] = { id = 29913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fleisch um jeden Preis", description = "Wie ich bereits sagte, sind meine Schweine sehr wählerisch. Sie brauchen Fleisch, um stark zu werden, aber sie mögen kein Hammelfleisch und kein Yak-Fleisch - und Schweinefleisch will ich ihnen schon gar nicht vorsetzen.\n\nSie fressen allerdings Mushan-Fleisch und mögen Schildkröten. Beides findet Ihr in großer Zahl im Westen.\n\nMeine Jagdfähigkeiten sind zugegebenermaßen ziemlich dürftig. Könnt Ihr einem jungen Bauern und seinen Schweinen helfen?", sourceObjective = "Besorgt 4 Mushanschulterstücke und 80 Fetzen Schildkrötenfleisch.", progress = "Es tut mir weh, sie vor Hunger quieken zu hören.\n\nWenn man eine Zeit lang Schweinebauer ist, erkennt man den Unterschied zu normalem Quieken.", completion = "<Liang sieht sich das Fleisch an.>\n\nIhr seid nicht nur ein {class}, sondern wohl auch ein Metzger, oder? Ihr habt ein Auge für hochwertige Schweinenahrung, Nachbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[29914] = { id = 29914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in den Stall", description = "Ich versuche stets, meine Tiere im Auge zu behalten, aber ab und zu büchst doch eins aus. Bei dem ganzen Chaos, das die Shed-Ling verursachen, wurde ich wohl für einen Moment etwas unachtsam und einige meiner Schweine konnten entkommen.\n\nWürdet Ihr sie für mich suchen? Ich würde als Erstes den Hügel runter Richtung Westen gehen.", sourceObjective = "Sucht Jian, Ling und Stinki.", progress = "Habt Ihr sie gefunden? Ich glaube, es fehlen drei.", completion = "Da sind sie ja! Los, zurück in den Schweinestall ihr drei!\n\n<Liang sieht zu Euch hoch.>\n\nVielen Dank, Nachbar. Ich weiß Eure Hilfe wirklich zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29915] = { id = 29915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachbarschaftliche Pflichten", description = "Ich bin wohl nicht der Einzige, der Probleme mit seinen Tieren hat. Eins von Francis' Schafen ist diese Woche schon zum dritten Mal zu mir auf den Hof gekommen. Vielleicht braucht er Hilfe beim Hüten seiner Herde?\n\nIhr solltet ihm einen Besuch abstatten, <Nachbar/Nachbarin>. Und nehmt bitte dieses arme Ding mit.", sourceObjective = "Bringt das entlaufene Lamm zu Francis dem Hirtenjungen.", progress = "Oh... Ihr habt eines meiner... meiner Lämmer?", completion = "Ihr hättet das Lamm wirklich nicht zu mir zurückbringen sollen. Es... Es war im Schweinestall sicherer aufgehoben als hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[29916] = { id = 29916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneidende Krallen und geifernde Schnäbel", description = "Zuerst kamen die Falken. Ihr habt bestimmt welche am Himmel kreisen sehen.\n\nKurz darauf folgten dann die Wölfe. Ich schätze, sie haben gerochen, dass ich schwach bin.\n\nIch bin nicht im Ansatz so tapfer, wie Meister Shang es dachte. Der Meister wird sich sehr über mich ärgern, wenn ich nichts gegen diese Bedrohungen unternehme.\n\nKönnt... könnt Ihr mir vielleicht helfen, <mein Herr/meine Dame>?", sourceObjective = "Tötet 5 diebische Ebenenfalken und 6 diebische Wölfe.", completion = "Sie... sie haben nicht aufgehört, aber zumindest haben wir uns zur Wehr gesetzt. Stimmt's?", sourceObjectiveStatus = "unverified-source-field" }
quests[29917] = { id = 29917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lupello", description = "Ich habe nachgedacht... Die Wölfe hören mit ihren Angriffen vielleicht auf, wenn wir ihren Leitwolf töten.\n\nWir nennen ihn Lupello, und er streift am gegenüberliegenden Ufer entlang.\n\n<Francis' Aufmerksamkeit wird von einem weiteren Angriff in Beschlag genommen. Vielleicht solltet Ihr Euch selbst um Lupello kümmern.>", sourceObjective = "Tötet Lupello.", completion = "Ich weiß, dass eigentlich ich gegen sie kämpfen sollte. Ich scheine wohl einfach nicht zum Hüten von Schafen geboren zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[29918] = { id = 29918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lektion in Sachen Tapferkeit", description = "<Meister Shang spricht mit seinem Hirtenjungen.>\n\nFrancis, du musst Tapferkeit zeigen! Du hast alles, was man braucht, um ein guter Hirte zu sein - du musst dich nur deinen Ängsten stellen!\n\n<Er sieht zu Euch rüber.>\n\nHeh, Ihr! Ihr habt doch schon dem Rest meiner Familie geholfen. Francis ist wie ein zweiter Sohn für mich.\n\nZeigt meinem Schüler, was Furchtlosigkeit bedeutet. Besiegt mit diesem Seil einen der großen weißen Falken über uns.\n\n<Shang zeigt zum Himmel, blickt zu Francis und geht.>", sourceObjective = "Verwendet das Viehhüterlasso, um einen großen weißen Ebenenfalken einzufangen und zu töten.", progress = "Ihr seid furchtlos. Das kann ich in Eurem Herzen spüren.", completion = "Francis braucht länger, als ich gedacht habe, um ein guter Hirte zu werden. Wir alle durchlaufen solche Phasen... Auch mein Sohn Liang war einmal schwach. Genauso wie ich.\n\nAber er wird es lernen. Das ist der Weg der Donnerfußens.", sourceObjectiveStatus = "unverified-source-field" }
quests[29919] = { id = 29919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei Dumme, ein Getränk", description = "Oh, hallo, {name}. Das ist jetzt schon das vierte Mal, dass wir uns begegnen, oder?\n\nNun... mein Fässchen wird ziemlich schnell immer leerer. Ich habe von einer Brauerei im Südwesten gehört. Wir sind auf dem Weg dorthin. Wollt Ihr uns begleiten?", sourceObjective = "Begleitet Chen Sturmbräu und Li Li zur Brauerei im Südwesten.", completion = "Wenn Ihr Bier sucht, seid Ihr hier genau richtig, Nachbar.\n\nHm, ähm... entschuldigt das Durcheinander. Hatte in den letzten Tagen ein Problem mit Shed-Ling.", sourceObjectiveStatus = "unverified-source-field" }
quests[29920] = { id = 29920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erlaubnis erhalten", description = "Mein Schatz Lo hat um die Erlaubnis der Pandriarchen ersucht, mich heiraten zu dürfen. Obwohl sie sich in anderen Sphären befinden, würde ihre Zustimmung uns viel bedeuten.\n\nDa sie jedoch Geister sind, konnten sie weder unsere Geschenke noch unsere Tribute beeindrucken. Um ihre Gunst zu gewinnen, verlangen sie, dass entweder Lo oder ein Champion einen der ihren im Kampf besiegt.\n\nLo ist ein guter Mann, aber kein Kämpfer.\n\nWollt Ihr unser Champion sein?", sourceObjective = "Fordert Pandriarch Zapfgold, Pandriarch Windpelz und Pandriarch Dornstab heraus und besiegt sie.", progress = "Die Pandriarchen haben sich ihren Ruf im Leben erworben und danach beibehalten. Ich weiß beim besten Willen nicht, wie Ihr sie besiegen wollt.", completion = "Sie… Sie haben zugestimmt?! Großartig! Vielen Dank! Dank ihres Segens werden wir die glücklichsten Pandaren des ganzen Landes sein!\n\nBitte nehmt das. Es sollte eigentlich ein Tribut an die Pandriarchen sein, aber sie waren nicht interessiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[29922] = { id = 29922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Weisheit", description = "Lehrensucher Cho hat während Eurer Abwesenheit nach Euch gefragt.\n\nEr braucht dringend Eure Hilfe im Ort Morgenblüte im Norden. Den Grund dafür hat er nicht genannt.\n\nSprecht mit Drachenmeister Ut-Nam. Er wird Euch mit Freuden dorthinschicken.", sourceObjective = "Sprecht mit Drachenmeister Ut-Nam, um nach Morgenblüte zu gelangen.", completion = "Eure Taten haben eine längst vergessene Erinnerung an eine uralte Prophezeiung hervorgerufen. Das muss untersucht werden.\n\nFür die Untersuchung benötige ich allerdings Jade. Ich habe Toya gebeten, so viel zu sammeln, wie er kann, und sie Euch zu geben, sobald er fertig ist. Bringt sie mir und wir werden versuchen, das uralte \"Omen des Kaisers\" zu entschlüsseln.\n\nWährend er Jade sammelt, könnt Ihr Euch hier gerne umsehen. Ihr werdet sehen, die Leute in diesem Ort können jemanden wie Euch gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
